L4_1 = {}
L4_1.m_CutScenKey_Talk = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 31622
L4_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Talk_KOREA = "저희 세계와 달리…… 이 세계에서 저는 무척 대우받고 있답니다."
L4_1.m_fTalkTime = 0.03
L4_1.m_bTalkCenterFadeIn = true
L4_1.m_Talk_JPN = "私たちとの世界とは違って……この世界で私は随分良い扱いを受けています。"
L4_1.m_Talk_ENG = "Unlike our world, I'm being treated with respect in this world."
L4_1.m_Talk_TWN = "不同於我們世界……我在這個世界受到的待遇還不錯。"
L4_1.m_Talk_THA = "ที่นี่มันต่างจากโลกของเรา แต่ฉันได้รับการปฏิบัติด้วยความรักในโลกนี้"
L4_1.m_Talk_VTN = "Không giống như thế giới của chúng ta, tôi được đối xử bằng sự tôn trọng ở thế giới này."
L4_1.m_Talk_SCN = "不同于我们世界……我在这个世界受到的待遇还不错。"
L4_1.m_Talk_DEU = "Im Gegensatz zu unserer Welt werde ich in dieser Welt mit Respekt behandelt."
L4_1.m_Talk_FRA = "Je suis traitée avec respect dans ce monde, contrairement au nôtre."
