L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Talk_KOREA = "우선, 이 세계에서는 먹고 싶은 건 언제든지, 얼마든지 먹을 수 있다구요?"
L8_1.m_fTalkTime = 0.03
L8_1.m_bTalkCenterFadeIn = true
L8_1.m_Talk_JPN = "まず、この世界では食べたいものをいつでも、好きなだけ食べられるんですよ？"
L8_1.m_Talk_ENG = "First, I can eat whatever I want, whenever I want."
L8_1.m_Talk_TWN = "在這個世界，我隨時可以吃我想吃的東西。"
L8_1.m_Talk_THA = "อย่างแรก ฉันสามารถกินอะไรก็ได้ที่อยากกิน และเมื่อไหร่ก็ได้ที่ฉันต้องการ"
L8_1.m_Talk_VTN = "Đầu tiên, tôi có thể ăn bất cứ thứ gì tôi muốn, bất cứ khi nào tôi muốn."
L8_1.m_Talk_SCN = "在这个世界，我可以随时吃我想吃的东西噢？"
L8_1.m_Talk_DEU = "Erstens kann ich in dieser Welt essen, was auch immer ich will und wann ich es will."
L8_1.m_Talk_FRA = "Tout d'abord, je peux manger ce que je veux, quand je veux."
L9_1 = {}
L9_1.m_CutScenKey_Talk = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 31622
L9_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Talk_KOREA = "겨우 칼로리 블록 하나로 깐깐하게 구는 카린 양과는 달리……"
L9_1.m_fTalkTime = 0.03
L9_1.m_bTalkCenterFadeIn = true
L9_1.m_Talk_JPN = "カロリーブロック一つで小言を言ってくるカリンさんとは違って……"
L9_1.m_Talk_ENG = "And unlike you, who is so stingy about one ration..."
L9_1.m_Talk_TWN = "與斤斤計較營養口糧的卡琳不同……"
L9_1.m_Talk_THA = "ที่นี่ไม่เหมือนคุณที่ตระหนี่ขี้เหนียวกับการแบ่งอาหารตลอด..."
L9_1.m_Talk_VTN = "Và không giống như cô, lúc nào cũng keo kiệt về khẩu phần ăn..."
L9_1.m_Talk_SCN = "和为了一个区区干口粮就变得执拗的卡琳不同……"
L9_1.m_Talk_DEU = "Und im Gegensatz zu dir, die so geizig ist, was auch nur einen Energieriegel angeht ..."
L9_1.m_Talk_FRA = "Et contrairement à vous, qui êtes si avare pour de simples rations..."
