L19_1.m_Pos = "R"
L19_1.m_Talk_KOREA = "대단하군요. 네로 란체스터 3세. 그대야말로 타의 모범이 되는 고양이라고 할 수 있어요."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "素晴らしいですね。ネロ・ランチェスター3世。あなたこそが他の猫たちの模範となる存在と言えそうです。"
L19_1.m_Talk_ENG = "Amazing. Nero Lanchester III. You are an exemplar of intelligence."
L19_1.m_Talk_TWN = "好棒喔，尼洛·蘭賈斯特三世，你是其他貓咪榜樣！"
L19_1.m_Talk_THA = "สุดยอดมาก นีโร แลนเชสเตอร์ที่ 3 เธอเป็นตัวอย่างของแมวที่แสนฉลาด"
L19_1.m_Talk_VTN = "Tuyệt vời. Nero Lanchester III. Em là một tấm gương về trí thông minh."
L19_1.m_Talk_SCN = "好棒哦，尼洛·兰切斯特三世。你是其他猫咪榜样！"
L19_1.m_Talk_DEU = "Großartig. Nero Lanchester III. Du bist eine Katze, an der sich andere ein Beispiel nehmen können."
L19_1.m_Talk_FRA = "Tu es incroyable, Nero Lanchester III. Un véritable exemple d'intelligence."
L20_1 = {}
L20_1.m_CutScenKey_Talk = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@20#Talk"
L20_1.m_CutScenProcessKey = 20
