L20_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L20_1.m_Pos = "R"
L20_1.m_Talk_KOREA = "역시 아카데미의 마스코트가 될 자격이 충분해요."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "やはりアカデミーのマスコットになるのに相応しい。"
L20_1.m_Talk_ENG = "You are more than qualified to be the Academy's mascot."
L20_1.m_Talk_TWN = "你果然有當學院吉祥物的資格！"
L20_1.m_Talk_THA = "เธอมีคุณสมบัติเกินกว่าที่จะเป็นตัวนำโชคของสถาบัน"
L20_1.m_Talk_VTN = "Em thừa tiêu chuẩn để trở thành linh vật của Học viện."
L20_1.m_Talk_SCN = "你果然有当学院吉祥物的资格！"
L20_1.m_Talk_DEU = "Du bist mehr als qualifiziert, das Maskottchen der Akademie zu werden."
L20_1.m_Talk_FRA = "Tu es plus que qualifié pour être la mascotte de l'Académie."
