L21_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L21_1.m_Pos = "R"
L21_1.m_Talk_KOREA = "자, 오늘도 상으로 최고급 무염 육포를 드리죠."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "さあ、今日もご褒美の最高級の減塩ジャーキーをあげましょう。"
L21_1.m_Talk_ENG = "Here's some top-quality unsalted beef jerky as a reward."
L21_1.m_Talk_TWN = "這是給你的獎勵，頂級無調味肉泥。"
L21_1.m_Talk_THA = "ต่อไปนี้เป็นเนื้อแดดเดียวคุณภาพดีจะเป็นรางวัลของเธอนะ"
L21_1.m_Talk_VTN = "Đây là phần thưởng món thịt bò khô không muối chất lượng hàng đầu."
L21_1.m_Talk_SCN = "给，今天也给你最高级无盐肉脯，就当是奖励了。"
L21_1.m_Talk_DEU = "Hier, nimm dieses hochwertige, ungesalzene Trockenfleisch als Belohnung."
L21_1.m_Talk_FRA = "Voici quelques tranches de bœuf séché sans sel de qualité supérieure en récompense."
