L24_1.m_Pos = "L"
L24_1.m_bCharPinup = true
L24_1.m_Talk_KOREA = "(후훗, 손 한번 내밀어 준 걸로, 고기를 내주다니. 나쁘지 않은 장사인데?)"
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "(ふふっ、お手を一回やるだけで肉が貰えるなんて。悪くない商売ね？)"
L24_1.m_Talk_ENG = "(Heh heh, getting meat just for giving out my paw, not a bad trade.)"
L24_1.m_Talk_TWN = "（呵呵，伸個手就有肉吃，很划算呢。）"
L24_1.m_Talk_THA = "(อิอิอิ ได้กินเนื้อเพียงเพราะขอให้เอาอุ้งเท้าให้ เป็นข้อแลกเปลี่ยนที่ไม่เลวเชียว)"
L24_1.m_Talk_VTN = "(He he, chỉ đưa chân ra cũng nhận được thịt, không phải là một giao dịch tệ đâu.)"
L24_1.m_Talk_SCN = "（啊哈，光是伸个手就能得到肉。这个买卖一点都不亏啊？）"
L24_1.m_Talk_DEU = "(Hehe, Fleisch zu bekommen, nur weil ich meine Pfote ausstrecke, ist kein schlechter Deal.)"
L24_1.m_Talk_FRA = "(Hé hé, obtenir de la viande juste pour avoir donné la patte, je ne m'en sors pas si mal.)"
L25_1 = {}
L25_1.m_CutScenKey_Talk = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 31622
L25_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_LAUGH"
L25_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L25_1.m_Pos = "L"
L25_1.m_bCharPinup = true
L25_1.m_Talk_KOREA = "(물론, 사람 입맛에는 약간 싱겁긴 하지만…… 뭐, 푸석 거리는 칼로리 블럭보다는 훨씬 좋아!)"
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "(まぁ、人間の私からすると少し味は薄いけど……まっ、ぱさぱさしてて食べづらいカロリーブロックよりはずっと良いか！)"
L25_1.m_Talk_ENG = "(Of course, it's not as salty as I'd like it to be... but it's a lot better than dry ration!)"
L25_1.m_Talk_TWN = "（當然，以人的口味來說有點淡……不過，還是比難吃的營養口糧強！）"
L25_1.m_Talk_THA = "(แต่จริงๆแล้ว มันจืดมากเลย น่าว่าจะเพิ่มความเค็มอีกสักหน่อยนะ)"
L25_1.m_Talk_VTN = "(Tất nhiên, nó không mặn như mình muốn... nhưng nó tốt hơn rất nhiều so với đồ khô!)"
L25_1.m_Talk_SCN = "（当然，对人的口味来说有点淡……不过，比难吃的干口粮强多了！）"
L25_1.m_Talk_DEU = "(Natürlich ist es nicht so salzig, wie ich es gerne hätte ... aber es ist viel besser als diese trockenen Energieriegel!)"
L25_1.m_Talk_FRA = "(Bien sûr, ce n'est pas aussi salé que j'aimerais que ça le soit... mais c'est beaucoup mieux que ces vieilles barres nutritives toutes sèches !)"
