L29_1.m_Pos = "R"
L29_1.m_Talk_KOREA = "네? 더 달라고요? 그렇지만…… 착한 고양이라면 참을 줄도 알아야 한답니다?"
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "はい？　もっとですか？　でも……お利巧な猫なら我慢することもできないとダメですよ？"
L29_1.m_Talk_ENG = "Pardon? You want more? Well... a good cat should know when to be patient."
L29_1.m_Talk_TWN = "什麼？你還想要嗎？可是……好貓咪要懂得忍耐喔。"
L29_1.m_Talk_THA = "ขอโทษนะ? เธออยากได้อะไรมากกว่านี้ไหม? ดีหละ...แมวที่ดีต้องรู้ว่า เวลาไหนควรรอก่อน  "
L29_1.m_Talk_VTN = "Sao cơ? Em muốn nhiều hơn nữa? À... một pé mèo ngoan nên biết khi nào cần kiên nhẫn."
L29_1.m_Talk_SCN = "什么？你还想吃？可是……乖猫猫要懂得忍耐噢？"
L29_1.m_Talk_DEU = "Was? Du möchtest mehr? Nun ... eine brave Katze sollte geduldig sein."
L29_1.m_Talk_FRA = "Pardon ? Tu en veux plus ? Eh bien... un gentil chat devrait savoir se montrer patient."
