L33_1 = "어쩜, 이리 부드러울 수가……. 치명적인 감촉이야……."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "なんと、なんという柔らかさ……致命的な触り心地だわ……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Oh my, how soft... Such an irresistible feeling..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "怎麼會這麼柔軟……這個致命的觸感……"
L32_1.m_Talk_TWN = L33_1
L33_1 = "โอ้ มันนุ่มมาก...   เป็นความรู้สึกที่ประทับใจจริงๆ..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Ôi chao, thật mềm mại... Cảm giác khó cưỡng quá."
L32_1.m_Talk_VTN = L33_1
L33_1 = "怎么会这么柔软……这个致命的手感……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Wow, wie unglaublich weich ... So ein unwiderstehliches Gefühl ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Oh mon Dieu, ce que tu es doux... je ne peux pas résister..."
L32_1.m_Talk_FRA = L33_1
