L33_1.m_Pos = "R"
L34_1 = "하나만, 딱 하나만 더 드리도록 하죠."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "もう一つ、もう一つだけあげます。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Just one. I'll give you one more."
L33_1.m_Talk_ENG = L34_1
L34_1 = "我就再給你一個，最後一個喔。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "แค่เธออีกอันนะ ฉันจะให้เธออีกหนึ่งอัน"
L33_1.m_Talk_THA = L34_1
L34_1 = "Chỉ một miếng nữa thôi. Chị sẽ cho em một miếng nữa."
L33_1.m_Talk_VTN = L34_1
L34_1 = "我就再给你一个，就一个。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Nur noch eins. Ich werde dir noch ein Leckerli geben."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Juste un. Je vais t'en donner juste un de plus."
