L36_1 = "으윽, 어쩔 수 없군요. 그럼 두 개……. 이 이상은 안 되요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "くっ、仕方ありませんね。じゃあ二つ……。これ以上はダメですよ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Ngh, all right. Two... but no more than that."
L35_1.m_Talk_ENG = L36_1
L36_1 = "唔，真拿你沒辦法，就給你二個吧……再多就不行囉。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "อืม เอาล่ะ งั้นสองอัน...แต่สุดท้ายละนะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Ơ, được rồi. Hai... nhưng không nhiều hơn thế."
L35_1.m_Talk_VTN = L36_1
L36_1 = "呃，没办法了。那我给你两个吧……再多就不行了。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Urgh, na gut. Zwei Leckerlis ... aber nicht mehr."
