L39_1 = "좋아요. 어쩔 수 없군요, 네로 란체스터 3세 당신이 이겼어요. 4개 드리죠."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "いいでしょう。仕方ありません、ネロ・ランチェスター3世。あなたの勝ちです。四つあげます。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Very well. All right. You win, Nero Lanchester III. I'll give you four."
L38_1.m_Talk_ENG = L39_1
L39_1 = "好吧，都怪我心太軟，尼洛·蘭賈斯特三世，你贏了，我給你四個。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ดีมากจ้า และแล้ว เธอก็ชนะ นีโร แลนเชสเตอร์ III ฉันจะให้เธอสี่อันเลยทีนี้"
L38_1.m_Talk_THA = L39_1
L39_1 = "Rất tốt. Được rồi. Em thắng, Nero Lanchester III. Chị sẽ cho em bốn miếng."
L38_1.m_Talk_VTN = L39_1
L39_1 = "好吧，没办法了。尼洛·兰切斯特三世，你赢了。我给你四个。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Na gut. In Ordnung. Du hast gewonnen, Nero Lanchester III. Ich werde dir vier Leckerlis geben."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Très bien. D'accord. Tu as gagné, Nero Lanchester III. Je vais t'en donner quatre."
L38_1.m_Talk_FRA = L39_1
