L41_1 = "UNIT_PRIDE"
L40_1.m_Face = L41_1
L40_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L40_1.m_Pos = "C"
L41_1 = "……대신 오늘은 하루 종일 저와 같이 있기에요?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "……その代わり今日は一日中私と一緒にいてくださいね？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "...But promise me you will stay with me all day, okay?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "……不過你要整天都和我黏在一起喔？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "...แต่ต้องสัญญากับฉันนะว่าเธอจะอยู่กับฉันทั้งวัน โอเคไหม?"
L40_1.m_Talk_THA = L41_1
L41_1 = "...Nhưng hứa với chị là em sẽ ở bên chị cả ngày nhé?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "……不过，你要一整天都和我在一起哦？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "... Aber versprich mir, dass du den ganzen Tag bei mir bleibst, okay?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Mais promets-moi que tu resteras avec moi toute la journée, d'accord...?"
L40_1.m_Talk_FRA = L41_1
