L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "낯선 세계……. 낯선 사람들……. 외롭지는 않냐고요?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L45_1.m_bTalkCenterFadeIn = true
L46_1 = "見慣れない世界……。見慣れない人たち……。寂しくならないかって？？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "An unfamiliar world... with unfamiliar people... Am I lonely?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "陌生的世界……陌生的人……你問我孤不孤單？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "โลกที่ไม่คุ้นเคย...กับคนที่ไม่คุ้นเคย...ฉันเหงาไหมนะหรอ?"
L45_1.m_Talk_THA = L46_1
L46_1 = "Một thế giới xa lạ...với những con người xa lạ...Tôi có cô đơn không?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "陌生的世界……陌生的人……你问我孤不孤单？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Eine unbekannte Welt ... mit unbekannten Menschen ... Bin ich nicht einsam?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Un monde inconnu... avec des gens inconnus... Si je me sens seule ?"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 31622
L46_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "후. 후. 후……. 걱정하지 마세요. 카린 양. "
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L46_1.m_bTalkCenterFadeIn = true
L47_1 = "ふ、ふ、ふ……ご心配はいりません。カリンさん。 "
L46_1.m_Talk_JPN = L47_1
L47_1 = "Heh. Heh. Heh... Worry not, Karin."
L46_1.m_Talk_ENG = L47_1
L47_1 = "呵，呵，呵……不用擔心，卡琳。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เฮ้ เฮ้ เฮ่... ไม่ต้องเป็นห่วงนะคาริน"
L46_1.m_Talk_THA = L47_1
L47_1 = "He he. He... Đừng lo, Karin."
L46_1.m_Talk_VTN = L47_1
L47_1 = "呼，呼，呼……不用担心，卡琳。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "He. He. He ... Keine Sorge, Karin."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Hé hé hé... Ne vous en faites pas, Karin."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
