L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "이곳 아카데미에도 카린 양처럼 괴롭힐 맛 나는 사람을 찾았거든요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L47_1.m_bTalkCenterFadeIn = true
L48_1 = "ここ、アカデミーでもカリンさんのようにいじめ甲斐のある対象を見つけましたから。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I've discovered someone in the Academy who's equally entertaining to harass as you."
L47_1.m_Talk_ENG = L48_1
L48_1 = "因為我在學院也有找到可以欺負的人，就像欺負卡琳一樣。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฉันได้เจอคนในสถาบันนี้ ที่สามารถไปก่อกวนได้พอๆกับเธอ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi đã phát hiện ra một người trong Học Viện cũng thích quấy rối như cô."
L47_1.m_Talk_VTN = L48_1
L48_1 = "因为我在学院找到了可以欺负的人，就像欺负卡琳你一样。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ich habe in der Akademie jemanden gefunden, den ich genauso gern ärgere wie dich, Karin."
L47_1.m_Talk_DEU = L48_1
L48_1 = "J'ai découvert quelqu'un dans l'académie qui est tout aussi divertissant à enquiquiner que vous."
L47_1.m_Talk_FRA = L48_1
