L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "R"
L4_1.m_Crash = 10
L5_1 = "원래 아카데미 최고의 마스코트 고양이는 이 몸, <color=#ffd34c>냥이엘</color>님이시다냥!"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "本来アカデミー最高のマスコット猫はこの私、<color=#ffd34c>ニャイエル</color>だったのニャ！"
L4_1.m_Talk_JPN = L5_1
L5_1 = "The best meow-scot of this Academy has always been me, <color=#ffd34c>Nya-iel</color>!"
L4_1.m_Talk_ENG = L5_1
L5_1 = "原本這個學院最棒的吉祥物是我，<color=#ffd34c>喵爾</color>欸，喵！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "เหมียวสกอตที่ดีที่สุดของสถาบันที่นี้คือฉัน<color=#ffd34c>แมวไอเอล</color>สิ!"
L4_1.m_Talk_THA = L5_1
L5_1 = "Người meo meo giỏi nhất Học viện này luôn là tao, <color=#ffd34c>Nya-iel</color>!"
L4_1.m_Talk_VTN = L5_1
L5_1 = "本来这个学院最棒的吉祥物是我，<color=#ffd34c>喵奈尔</color>大人啊喵！"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Das beste Maskottchen dieser Akademie war schon immer ich, <color=#ffd34c>Miau-Naielle</color>!"
L4_1.m_Talk_DEU = L5_1
L5_1 = "C'est moi la meilleure mascotte de cette Académie, moi, <color=#ffd34c>Niaouelle</color> !"
L4_1.m_Talk_FRA = L5_1
