L6_1[1] = L7_1
L6_1[2] = L8_1
L5_1.m_Bounce = L6_1
L6_1 = "어디 굴러들어온 돌 주제에 감히 그 자리를 뺏는 거냥!?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "いきなり転がり込んできたような奴に、その座を奪われてたまるかニャ！？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "How dare you try to take my place as the established meow-scot?!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "懂不懂先來後到，你膽敢搶走我的位置，喵？！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "กล้าดียังไงมาแทนที่ฉันในฐานะเหมี๋ยวสกอตที่ตั้งขึ้น!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Sao mày dám cố chiếm lấy vị trí của tao là meow-scot đã thành danh hả?!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "懂不懂先来后到，你胆敢抢走我的位置啊喵？！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Wie kannst du es wagen, meinen Platz als etabliertes Miauskottchen einzunehmen?!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Comment oses-tu essayer de prendre ma place en tant que miaouscotte ?!"
L5_1.m_Talk_FRA = L6_1
