L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "R"
L7_1 = 40
L6_1.m_Crash = L7_1
L7_1 = "다들 눈이 삔 게 분명하다냥! 이런 족보 없는 길냥이가 뭐가 좋다고 난리인 거다냥!?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "みんな目がどうかしているのニャ！　こんなどこの馬の骨かもわからない野良猫のどこがいいのニャ！？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Hiss! Everyone must be seeing things! What's there to like about this mongrel?!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "大家眼睛有問題嗎，喵！這種來路不明的流浪貓有什麼好的，喵？！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ฟ่อ! ทุกคนจะต้องได้รู้ทุกสิ่ง! ว่ามันมีอะไรที่ไม่ชอบเกี่ยวกับเจ้าแมวสายพันธ์นี้!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Xì! Mọi người chắc hẳn đã nhìn thấy mọi thứ! Con lai này có gì để thích chứ?!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "大家肯定都是看走眼了喵！这种不知根底的流浪猫有什么好的喵？！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Die müssen alle Tomaten auf den Augen haben! Was soll die ganze Aufregung um eine streunende Katze?!"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Pfft ! Ils ont tous perdu la tête, ou quoi ? Qu'est-ce qu'ils peuvent bien trouver à ce chat de gouttière ?!"
L6_1.m_Talk_FRA = L7_1
