L10_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 31622
L9_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_SURPRISE"
L9_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L9_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L9_1.m_Pos = "L"
L9_1.m_bCharPinup = true
L10_1 = "(으응? 뭐지, 얘는 자기가 고양이 인줄 아나 봐? 뭔가 근본 없는 컨셉인데?)"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "(ん？　何、この子。自分のこと猫だと思っているの？　何なの、この薄っぺらい設定は。)"
L9_1.m_Talk_JPN = L10_1
L10_1 = "(Erm, huh? Does she think she's a cat? That's a strange act to pull.)"
L9_1.m_Talk_ENG = L10_1
L10_1 = "（嗯？什麼東西，她以為自己是貓嗎？什麼無厘頭的人設？）"
L9_1.m_Talk_TWN = L10_1
L10_1 = "(เอ่อ เหรอ เธอคิดว่าตัวเองเป็นแมวนี่น้อ? นั่นเป็นการขู่ที่แปลกดีนะ)"
L9_1.m_Talk_THA = L10_1
L10_1 = "(Ừm, hả? Cô ấy nghĩ mình là một con mèo à? Thật là một hành động kỳ lạ.)"
L9_1.m_Talk_VTN = L10_1
L10_1 = "（嗯？什么啊，她以为自己是猫吗？感觉很像无厘头的人设啊？）"
L9_1.m_Talk_SCN = L10_1
L10_1 = "(Ähm, wie bitte? Glaubt sie etwa, dass sie eine Katze ist? Was für eine seltsame Show zieht die denn ab?!)"
L9_1.m_Talk_DEU = L10_1
L10_1 = "(Hein ? Elle se prend pour un chat ? Plutôt étrange comme concept.)"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@60#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 60
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 31622
L10_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_IDLE"
L10_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L10_1.m_Pos = "L"
L10_1.m_bCharPinup = true
L11_1 = "(후훗, 그래도 재밌어서 좋네. 아카데미에는 별난 친구들이 많구나.)"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "(ふふっ、でも面白いからいっか。アカデミーには変わった子がたくさんいるのね。)"
L10_1.m_Talk_JPN = L11_1
L11_1 = "(Heh heh, still, it's an interesting place. There's a lot of eccentric kids in this Academy.)"
L10_1.m_Talk_ENG = L11_1
L11_1 = "（呼呼，不過好有趣，學院有很多奇特的孩子呢。）"
L10_1.m_Talk_TWN = L11_1
L11_1 = "(อิอิ ถึงยังไงที่นี่ยังคงเป็นสถานที่น่าสนใจ มีเด็กประหลาดมากมายในสถาบันนี้ด้วย)"
L10_1.m_Talk_THA = L11_1
L11_1 = "(He he, đây vẫn là một nơi thú vị. Có rất nhiều đứa trẻ lập dị trong Học viện này.)"
L10_1.m_Talk_VTN = L11_1
L11_1 = "（呼呼，不过好有趣，学院有很多奇特的孩子们。）"
L10_1.m_Talk_SCN = L11_1
L11_1 = "(Hehe, es ist trotzdem ein interessanter Ort. Es gibt viele exzentrische Kinder in dieser Akademie.)"
L10_1.m_Talk_DEU = L11_1
L11_1 = "(Hé hé, mais cet endroit est des plus intéressants. Cette Académie regorge d'enfants excentriques.)"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 31622
L11_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L11_1.m_Pos = "L"
L11_1.m_bCharPinup = true
L12_1 = "(나도 학교 끝까지 다녔으면 좋았을 텐데…….)"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "(私も学校をちゃんと卒業したかったな……)"
L11_1.m_Talk_JPN = L12_1
L12_1 = "(Would've been nice if I finished school, too...)"
L11_1.m_Talk_ENG = L12_1
L12_1 = "（真希望我那時堅持上完學……）"
L11_1.m_Talk_TWN = L12_1
L12_1 = "(คงจะดีมาก ถ้าฉันเรียนจบ...)"
L11_1.m_Talk_THA = L12_1
L12_1 = "(Sẽ thật tuyệt nếu mình cũng được học xong...)"
L11_1.m_Talk_VTN = L12_1
L12_1 = "（如果那时我坚持上完学就好了……）"
L11_1.m_Talk_SCN = L12_1
L12_1 = "(Es wäre schön gewesen, wenn ich auch diese Schule absolviert hätte ...)"
L11_1.m_Talk_DEU = L12_1
L12_1 = "(Si seulement j'avais pu terminer mes études, moi aussi...)"
L11_1.m_Talk_FRA = L12_1
