L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "R"
L15_1 = 40
L14_1.m_Crash = L15_1
L15_1 = "뭐냥!! 왜 째려보냥!! 지금 나한테 도전하는 거냥!?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "何だニャ！！　何にらみつけてやがるニャ！！　私に挑もうってのかニャ！？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Hiss! What are you looking at?! Are you challenging me to a duel?!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "幹嘛！為什麼瞪我，喵！你這是在挑釁我，喵？！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ฟ่อ! สิ่งที่เธอต้องการจากที่นี่คืออะไร?! เธอกำลังยั่วโมโหฉันหรอ?!"
L14_1.m_Talk_THA = L15_1
L15_1 = "Xì! Mày đang nhìn gì đó?! Định thách đấu tay đôi với tao à?!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "干嘛！为什么瞪我喵！你这是在挑衅我喵？！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "*Fauch* Warum starrst du mich so an!! Forderst du mich zu einem Duell heraus?!"
L14_1.m_Talk_DEU = L15_1
L15_1 = "*Souffle* C'est quoi ce regard, hein ?! Tu veux me provoquer en duel, miaou ?!"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
