L16_1 = "NAIEL_CAT_NPC_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "R"
L16_1 = "좋아, 고양이 대 고양이로서 그 영역다툼 받아주겠다냥! 덤벼라, 냥!!"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "よし、その猫同士の縄張り争い、受けて立つ！　かかってこい、ニャン！！"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Fine, from one cat to another, I'll fight for this territory! Come at me-ow!"
L15_1.m_Talk_ENG = L16_1
L16_1 = "很好，我接受這場貓咪對貓咪的決鬥，喵！放馬過來吧，喵！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "เอาล่ะ จากแมวตัวหนึ่งเพิ่มไปอีกตัวหนึ่ง ฉันจะต่อสู้เพื่อดินแดนนี้ของฉัน! ตามฉันมา-เหมี่ยว!"
L15_1.m_Talk_THA = L16_1
L16_1 = "Được thôi, con mèo này đến con mèo khác, tao sẽ chiến đấu vì lãnh thổ này! Đến đây!"
L15_1.m_Talk_VTN = L16_1
L16_1 = "很好，我接受这场喵对喵的决斗啊喵！放马过来吧，喵！"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Also gut, von einer Katze zur anderen, ich werde für dieses Territorium kämpfen, miau! Komm her, miau!"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Très bien, d'un chat à l'autre, je me battrai pour ce territoire, miaou ! Allez, ramène-toi !"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
