L17_1 = 40
L16_1.m_Crash = L17_1
L17_1 = "대신 내가 이기면, 내 영역에는 얼씬도 하지 말기다냥!!"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "その代わり、私が勝てば、二度とここには近づくニャ！！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "But if I win, you better not come across my territory ever again! Hiss!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "如果我贏了，你就不准再出現在我的地盤，喵！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ถ้าฉันชนะ อย่ามาก้าวก่ายดินแดนของฉันอีกนะ! ฟ่อ!"
L16_1.m_Talk_THA = L17_1
L17_1 = "Nhưng nếu tao thắng, tốt nhất mày đừng bao giờ đi ngang qua lãnh thổ của tao nữa! Xìiiii!"
L16_1.m_Talk_VTN = L17_1
L17_1 = "如果我赢了，就再也不要出现在我的领地喵！"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Aber wenn ich gewinne, lässt du dich besser nie wieder in mein Territorium blicken, miau! *Fauch*"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Mais si je gagne, tu ferais mieux de ne plus jamais remettre les pattes sur mon territoire, miaou ! *Souffle*"
L16_1.m_Talk_FRA = L17_1
