L20_1.m_Bounce = L21_1
L21_1 = "정신 좀 차려, 나이엘! 넌 고양이가 아니라, 사람이라고!!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "いい加減にして、ナイエル！　あなたは猫じゃなくて、人間！！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Get it together, Naielle! You're a person, not a cat!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "醒醒吧，奈爾！你不是貓，你是人！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ไปกันนะไอเอล! เธอเป็นคนนะ ไม่ใช่ลูกแมว!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Tỉnh lại đi, Naielle! Cô là người chứ không phải mèo!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "醒醒吧，奈尔！你不是猫，你是人！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Reiß dich zusammen, Naielle! Du bist ein Mensch, keine Katze!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Arrête un peu tes idioties, Naielle ! Tu es un humain, pas un chat !"
L20_1.m_Talk_FRA = L21_1
