L21_1.m_Pos = "R"
L21_1.m_Crash = 30
L22_1 = "잠깐, 고양이가 되는 최면에 걸렸을 뿐이라니깐!?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "ちょっとだけ、猫になる催眠にかかっているだけだってば！？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "I just hypnotized you into becoming a cat for a short duration!"
L21_1.m_Talk_ENG = L22_1
L22_1 = "不要這樣，你只是被催眠成貓而已！"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ฉันสะกดจิตเธอให้กลายเป็นแมวในช่วงเวลาสั้นๆเอง!"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tôi chỉ thôi miên cô trở thành một con mèo trong một thời gian ngắn thôi!"
L21_1.m_Talk_VTN = L22_1
L22_1 = "等等，你只是被催眠成了猫而已！"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ich habe dich gerade für kurze Zeit hypnotisiert, damit du zu einer Katze wirst!"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Je t'ai juste hypnotisée pour que tu deviennes un chat pendant quelque temps !"
L21_1.m_Talk_FRA = L22_1
