L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "L"
L23_1 = 40
L22_1.m_Crash = L23_1
L23_1 = "시끄럽다냥!! 누가 너 같은 삼류 마술사의 최면에 걸린다는 거다냥!?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "うるさいんだニャ！！　誰があんたみたいな三流マジシャンの催眠にかかるんだニャ！？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Enough! Hiss! I would never fall for a C-list magician's hypnosis!"
L22_1.m_Talk_ENG = L23_1
L23_1 = "你騙人，喵！誰會被你這種三流魔術師催眠，喵？！"
L22_1.m_Talk_TWN = L23_1
L23_1 = "พอ! ฟ่อ! ฉันจะไม่มีวันตกหลุมการสะกดจิตของนักมายากลระดับ C!"
L22_1.m_Talk_THA = L23_1
L23_1 = "Đủ rồi! Xùy! Tôi sẽ không bao giờ bị mê hoặc bởi thuật thôi miên của đồ ảo thuật gia hạng ba!"
L22_1.m_Talk_VTN = L23_1
L23_1 = "吵死了！谁会被你这种三流魔术师催眠喵？！"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Halte die Klappe! *Fauch* Ich würde niemals auf die Hypnose einer drittklassigen Zauberin hereinfallen, miau!"
L22_1.m_Talk_DEU = L23_1
L23_1 = "N'importe quoi ! *Souffle* Je ne me laisserais jamais hypnotiser par une magicienne de pacotille !"
L22_1.m_Talk_FRA = L23_1
