L25_1 = "NAIEL_CAT_NPC_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "이 몸은 원래부터 고양이었던 것이다냥! 그것도 아카데미 최고의 고양이다냥!"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "この私は初めから猫だったニャ！　それもアカデミー最高の猫だニャ！"
L24_1.m_Talk_JPN = L25_1
L25_1 = "I was always a cat! The best cat in the academ-eow!"
L24_1.m_Talk_ENG = L25_1
L25_1 = "我本來就是貓！而且還是學院裡最棒的貓，喵！"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ฉันก็ยังเป็นแมวอยู่เสมอ! แมวที่ดีที่สุดในสถาบัน-เหมี๋ยว!"
L24_1.m_Talk_THA = L25_1
L25_1 = "Tôi đã luôn là một con mèo! Con mèo giỏi nhất trong học viện meow!"
L24_1.m_Talk_VTN = L25_1
L25_1 = "本尊本来就是猫咪！而且还是学院最棒的猫咪啊喵！"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Ich war schon immer eine Katze, miau! Die Top-Katze in der gesamten Akademie, miau!"
L24_1.m_Talk_DEU = L25_1
L25_1 = "J'ai toujours été un chat ! Le meilleur chat de l'Académie, miaou !"
L24_1.m_Talk_FRA = L25_1
