L26_1 = "그리고 최고의 고양이는 오직 한 마리뿐이다냥!"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "そして最高の猫になれるのは一匹のみニャ！"
L25_1.m_Talk_JPN = L26_1
L26_1 = "And there can only be one meow-scot!"
L25_1.m_Talk_ENG = L26_1
L26_1 = "而且，最棒的貓只能有一隻！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "และก็มีเหมียวสก๊อตตัวนั่นด้วย!"
L25_1.m_Talk_THA = L26_1
L26_1 = "Và chỉ có thể có một meow-scot!"
L25_1.m_Talk_VTN = L26_1
L26_1 = "而且，最棒的猫咪只能有一只！"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Und es kann nur eine Top-Katze geben, miau!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Et il ne peut y avoir qu'un seul meilleur chat ici, miaou !"
L25_1.m_Talk_FRA = L26_1
