L26_1.m_Crash = 30
L27_1 = "덤벼라냥! 너 같은 족보 없는 길양이는 이 냥이엘님이 한 방에 쓰러트러 주겠다냥!"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "かかって来るんだニャ！　あんたのような野良猫はこのニャイエル様が一発でKOしてやるニャ！"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Come-ow-n! I can beat a stray cat like you with one punch! Hiss!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "放馬過來吧！像你這種來路不明的流浪貓，我喵爾一拳就能打倒你！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "มา-มา นี่ นะ-เหมี๋ยวๆ! ฉันจะเอาชนะแมวจรจัดอย่างเธอเพียงหมัดเดียว! ฟ่อ!"
L26_1.m_Talk_THA = L27_1
L27_1 = "Nàooo! Tao có thể đánh bại một con mèo hoang như mày chỉ bằng một cú đấm! Xì!"
L26_1.m_Talk_VTN = L27_1
L27_1 = "放马过来吧！像你这种毫无根底的流浪猫，本喵奈尔大人一拳就能打倒你！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Komm schon! Ich kann eine streunende Katze wie dich mit einem Schlag besiegen, miau! *Fauch*"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Allez ! Je peux battre un chat errant comme toi d'un seul coup de poing, miaou ! *Souffle*"
L26_1.m_Talk_FRA = L27_1
