L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L46_1.m_bTalkCenterFadeIn = true
L47_1 = "地下シェルターの冷たい床と臭い寝袋とはもうさようなら～"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Adieu to the cold floor and smelly sleeping bag of the underground shelter!"
L46_1.m_Talk_ENG = L47_1
L47_1 = "再也不用睡地下庇護中心冰冷的地板和發臭的睡袋～"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ลาก่อนนะพื้นเย็นๆ และถุงนอนที่กลิ่นเน่าๆจากพื้นใต้ดิน!"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tạm biệt sàn nhà lạnh lẽo và chiếc túi ngủ bốc mùi của hầm trú ẩn dưới lòng đất!"
L46_1.m_Talk_VTN = L47_1
L47_1 = "再也不用睡地下避难所冰冷的地板和发臭的睡袋咯。"
