L48_1 = "저만의 특별한 요람이 24시간 상시 대기하고 있단 말씀!"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L47_1.m_bTalkCenterFadeIn = true
L48_1 = "私専用のベッドが24時間常時待機しているんです！"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Here, I have my own special cradle standing by 24/7!"
L47_1.m_Talk_ENG = L48_1
L48_1 = "專屬於我的搖籃，24小時供我使用！"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ที่นี่ ฉันมีเปลพิเศษของตัวเองคอยให้บริการตลอด 24 ชั่วโมงทุกวันด้วย!"
L47_1.m_Talk_THA = L48_1
L48_1 = "Ở đây, tôi có chiếc nôi đặc biệt của riêng mình luôn sẵn sàng 24/7!"
L47_1.m_Talk_VTN = L48_1
L48_1 = "只属于我的特别摇篮，24小时供我使用！"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Hier, steht meine eigene spezielle Wiege rund um die Uhr für mich bereit!"
L47_1.m_Talk_DEU = L48_1
