L49_1 = "포근하고…… 또 아주 따뜻한…… 사람의 체온을 느낄 수 있는 곳이랍니다?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L48_1.m_bTalkCenterFadeIn = true
L49_1 = "柔らかいし……そしてすごく暖かい……人間の温もりを感じられる場所なんですよ？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "It's ever so soft... and you can feel the warm embrace of a person."
L48_1.m_Talk_ENG = L49_1
L49_1 = "是個舒適……而且很溫暖的……可以感受到人類體溫的地方呢。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "มันนุ่มสบายเหลือเกิน...เหมือนสัมผัสได้ถึงอ้อมกอดอันอบอุ่นของใครคนหนึ่ง"
L48_1.m_Talk_THA = L49_1
L49_1 = "Nó thật mềm mại... và còn có thể cảm nhận được vòng tay ấm áp của một người."
L48_1.m_Talk_VTN = L49_1
L49_1 = "是个舒适……而且很温暖的……可以感受到人类体温的地方噢？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Es ist so weich ... und warm ... Ich kann die Körpertemperatur einer Person spüren."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Tellement doux... On dirait l'étreinte chaleureuse d'une personne."
L48_1.m_Talk_FRA = L49_1
