L13_1 = "あはは、ノワール少佐……柔らかくて……暖かくて……気持ちいい……"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Ah ha ha, Major Noir... So soft... and warm... So nice..."
L12_1.m_Talk_ENG = L13_1
L13_1 = "哈哈，黑嚕嚕少校……你好柔軟喔……又暖暖的……真舒服……"
L12_1.m_Talk_TWN = L13_1
L13_1 = "อ่า ฮ่าฮ่า พันตรีนัวร์... นุ่ม...อุ่น...ดีจัง..."
L12_1.m_Talk_THA = L13_1
L13_1 = "Ah ha ha, Thiếu tá Noir... Mềm quá... và ấm áp... Dễ chịu quá..."
L12_1.m_Talk_VTN = L13_1
L13_1 = "啊哈哈，努亚尔少校……你很柔软……又温暖……心情真好……"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ahahaha, Major Noir ... So weich ... und warm ... Es fühlt sich so gut an ..."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Ha ha ha, major Noir... Tu es si doux... Si chaud... C'est si agréable..."
L12_1.m_Talk_FRA = L13_1
