L15_1 = "(후후, 포근한 펭귄인형과 따뜻한 소녀의 품…….)"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "(ふふ、柔らかいペンギンの人形と少女の胸の中……)"
L14_1.m_Talk_JPN = L15_1
L15_1 = "(Heh heh, the warm embrace of a girl and a soft penguin plushie...)"
L14_1.m_Talk_ENG = L15_1
L15_1 = "（呵呵，柔軟的企鵝娃娃和溫暖的少女懷抱……）"
L14_1.m_Talk_TWN = L15_1
L15_1 = "(ฮิฮิ อ้อมกอดอันแสนอบอุ่นของหญิงสาวและตุ๊กตานกแพนกวินแสนนุ่ม...)"
L14_1.m_Talk_THA = L15_1
L15_1 = "(He he, cái ôm ấm áp của một cô gái và chú chim cánh cụt mềm mại...)"
L14_1.m_Talk_VTN = L15_1
L15_1 = "（呼呼，柔软的企鹅公仔和温暖的少女怀抱……）"
L14_1.m_Talk_SCN = L15_1
L15_1 = "(Hehe, die wärmende Umarmung eines Mädchens und eines weichen Pinguin-Plüschtiers ...)"
L14_1.m_Talk_DEU = L15_1
L15_1 = "(Hé hé, l'étreinte chaleureuse d'une peluche de pingouin et de cette fille...)"
L14_1.m_Talk_FRA = L15_1
