L16_1 = "(역시 여기만큼 편안한 곳이 없네.)"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "(やっぱりここ以上に安らぐ場所はないよね。)"
L15_1.m_Talk_JPN = L16_1
L16_1 = "(It's so comfortable here.)"
L15_1.m_Talk_ENG = L16_1
L16_1 = "（有比這裡更舒服的地方嗎？）"
L15_1.m_Talk_TWN = L16_1
L16_1 = "(ที่นี่สบายมาก)"
L15_1.m_Talk_THA = L16_1
L16_1 = "(Ở đây thật thoải mái.)"
L15_1.m_Talk_VTN = L16_1
L16_1 = "（没有比这里更舒服的地方了吧。）"
L15_1.m_Talk_SCN = L16_1
L16_1 = "(Es gibt keinen bequemeren Ort als hier.)"
L15_1.m_Talk_DEU = L16_1
L16_1 = "(C'est tellement agréable ici.)"
L15_1.m_Talk_FRA = L16_1
