L17_1 = "(배부르게 먹고, 실컷 몸을 움직인 뒤라서…… 금방 잠들 것만 같아.)"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "(思う存分食べて、思いっきり身体を動かしたから……すぐに眠れそう。)"
L16_1.m_Talk_JPN = L17_1
L17_1 = "(I was going around with a full stomach, and now... I'm sleepy...)"
L16_1.m_Talk_ENG = L17_1
L17_1 = "（吃得飽飽的，盡情活動完身體……馬上就可以入睡。）"
L16_1.m_Talk_TWN = L17_1
L17_1 = "(ฉันเที่ยวกินจนท้องตึง แต่ตอนนี้... ฉันเริ่มง่วงแล้ว...)"
L16_1.m_Talk_THA = L17_1
L17_1 = "(Tôi đang đi loanh quanh với cái bụng no căng, và bây giờ... tôi buồn ngủ quá...)"
L16_1.m_Talk_VTN = L17_1
L17_1 = "（吃得饱饱的，尽情地活动完身体……现在感觉马上就要睡着了。）"
L16_1.m_Talk_SCN = L17_1
L17_1 = "(Ich bin mit vollem Magen zu viel herumgelaufen und jetzt ... bin ich müde ...)"
L16_1.m_Talk_DEU = L17_1
L17_1 = "(J'ai bien mangé et bien bougé... Je crois que je vais m'endormir en moins de deux.)"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
