L18_1 = "(이런 일상…… 꽤…… 나쁘지 않은데…….)"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "(こういう日常……割と……悪くないな……)"
L17_1.m_Talk_JPN = L18_1
L18_1 = "(This life... isn't too bad...)"
L17_1.m_Talk_ENG = L18_1
L18_1 = "（這種生活……其實……還蠻不錯的……）"
L17_1.m_Talk_TWN = L18_1
L18_1 = "(ชีวิตแมวนี่...ก็ไม่ได้แย่นะ...)"
L17_1.m_Talk_THA = L18_1
L18_1 = "(Cuộc sống này... cũng không tệ lắm...)"
L17_1.m_Talk_VTN = L18_1
L18_1 = "（这种日常……其实……还挺不错……）"
L17_1.m_Talk_SCN = L18_1
L18_1 = "(Dieses Leben ... ist echt nicht schlecht ...)"
L17_1.m_Talk_DEU = L18_1
L18_1 = "(Cette vie... n'est pas si mal...)"
L17_1.m_Talk_FRA = L18_1
