L25_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 31622
L24_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "어때요, 카린 양? 보시다시피 저는 잘 지내고 있답니다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L24_1.m_bTalkCenterFadeIn = true
L25_1 = "どうですか、カリンさん？　見ての通り私は元気でやっています。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "What do you think, Karin? As you can see, I'm doing well."
L24_1.m_Talk_ENG = L25_1
L25_1 = "怎麼樣，卡琳？如你所見，我過得很好。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "เธอคิดยังไงบ้างน้อคาริน? ถ้าเธอได้เห็น ตอนนี้ฉันสบายดี  "
L24_1.m_Talk_THA = L25_1
L25_1 = "Cô nghĩ sao, Karin? Như cô thấy, tôi đang sống rất tốt."
L24_1.m_Talk_VTN = L25_1
L25_1 = "怎么样，卡琳？如你所见，我过得很好。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Was denkst du, Karin? Wie du siehst, geht es mir gut."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Qu'en pensez-vous, Karin ? Comme vous pouvez le voir, je vais bien."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 31622
L25_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "인간이 아닌 게 아쉽지만, 고양이의 삶도 그럭저럭 괜찮은 것 같더라고요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L25_1.m_bTalkCenterFadeIn = true
L26_1 = "人間じゃないことは残念だけど、猫としての暮らしもなかなか悪くはありません。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "It's a shame I'm not human, but living as a cat isn't so bad."
L25_1.m_Talk_ENG = L26_1
L26_1 = "雖然不是人類有點可惜，但貓咪的生活也蠻不錯的。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "แต่น่าเสียดายที่ฉันไม่ใช่มนุษย์สิ  แต่การใช้ชีวิตแบบแมวก็ไม่ได้เลวร้ายนะ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Thật tiếc là tôi không phải là con người, nhưng sống như một con mèo cũng không tệ lắm."
L25_1.m_Talk_VTN = L26_1
L26_1 = "虽然不是人类有点可惜，但猫咪的生活也挺不错。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Es ist schade, dass ich kein Mensch bin, aber als Katze zu leben ist gar nicht so schlimm."
L25_1.m_Talk_DEU = L26_1
L26_1 = "C'est dommage que je ne sois pas humaine, mais vivre une vie de chat n'est pas si déplaisante."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 31622
L26_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "뭐, 아무렴. 멸망을 앞둔 세계보다 하루하루 치열하게 살아가는 것보단……"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L26_1.m_bTalkCenterFadeIn = true
L27_1 = "まぁ、何にせよ。滅亡が目前に迫っている世界で、毎日を壮絶に生きるより……"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I mean, wouldn't it be better to live as a cat, in a cozy world..."
L26_1.m_Talk_ENG = L27_1
L27_1 = "總之，與其在瀕臨滅亡的世界過著激烈的每一天……"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ฉันหมายถึงว่า ถ้าอยู่อย่างแมวดีกว่าในโลกที่แสนสบายมันก็คุ้ม..."
L26_1.m_Talk_THA = L27_1
L27_1 = "Ý tôi là, sống như một con mèo trong một thế giới ấm cúng chẳng phải sẽ tốt hơn sao..."
L26_1.m_Talk_VTN = L27_1
L27_1 = "总之，与其在濒临灭亡的世界过着激烈的每一天……"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ich meine, wäre es nicht besser, als Katze in einer gemütlichen Welt zu leben ..."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Finalement, ne serait-il pas préférable de vivre en tant que chat dans un monde confortable..."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 31622
L27_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "고양이라도 안락한 세상에서 사는 게 낫지 않겠어요?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L27_1.m_bTalkCenterFadeIn = true
L28_1 = "猫でも安らぎのある世界で生きる方が良いでしょう？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Rather than trying desperately to survive in a world of imminent doom?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "還不如作為一隻貓生活在和平的世界。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ดีกว่าพยายามสุดชีวิตเพื่อเอาชีวิตรอดในโลกแห่งความพินาศที่ใกล้ๆเข้ามาถึงใช่ไหม?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Thay vì cố gắng hết sức để tồn tại trong một thế giới sắp diệt vong?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "还不如作为一只猫生活在平和的世界。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Anstatt verzweifelt zu versuchen, in einer Welt, am Rande der Zerstörung zu überleben?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Plutôt que d'essayer désespérément de survivre dans un monde dont la fin est imminente ?"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
