L30_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 31622
L29_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L29_1.m_bWaitClick = true
