L30_1 = "m_BGCrash"
L29_1[L30_1] = 20
L30_1 = "m_fBGCrashTime"
L29_1[L30_1] = 1
L30_1 = "FX_CUTSCEN_TADA"
L29_1.m_StartFXSoundName = L30_1
L30_1 = "이왕 이렇게 된 거…… 즐길 만큼 즐기다 가려고요!!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L29_1.m_bTalkCenterFadeIn = true
L30_1 = "こうなった以上……思う存分に楽しんでから帰りますってことです！！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Since I'm here anyway... might as well enjoy it!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "事以致此……我決定盡情享受後再回去！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฉันอยู่ที่นี่...มันก็อาจจะสนุกกว่าก็ได้!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Vì dù sao thì tôi cũng tới đây... nên tận hưởng nó vậy!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "既然都这样了……那我要尽情地享受之后再回去！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Da ich sowieso hier bin ... sollte ich es so gut wie möglich genießen!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Puisque je suis bloquée ici de toute façon... autant en profiter !"
L29_1.m_Talk_FRA = L30_1
