L31_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 31622
L30_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "어차피, 지금까지 그래왔던 것처럼 적당히 돌아갈 수 있겠죠?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L30_1.m_bTalkCenterFadeIn = true
L31_1 = "どうせ、今までもそうだったし、結局は戻れるでしょ？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I'm sure things are going to be fine without me, right?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "反正，就跟以前一樣，我應該能在適當的時候回去吧？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ฉันเชื่อว่าสิ่งต่างๆที่นั่น จะผ่านไปด้วยดีหากโลกนั้นไม่มีฉันใช่ไหม?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi chắc chắn mọi chuyện sẽ ổn thôi nếu không có tôi, nhỉ?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "反正，就像一直以来那般，我应该能在适当的时候回去吧？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich bin sicher, dass ohne mich bestimmt alles gut wird."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je suis sûre que les choses iront bien même sans moi, non ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 31622
L31_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "후후후. 저 없는 동안 고생 좀 하시라구요, 카린 양~"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L31_1.m_bTalkCenterFadeIn = true
L32_1 = "ふふふ。私がいない間、頑張ってくださいね、カリンさん～"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Heh heh heh. Good luck with all the trouble without me by your side, Karin."
L31_1.m_Talk_ENG = L32_1
L32_1 = "嘿嘿嘿，我不在的這段時間就辛苦你囉，卡琳～"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เฮ้ เฮ้ เฮ้ งั้นฉันขอให้โชคดีกับทุกปัญหาในโลกนั้นหากไม่มีฉันอยู่เคียงข้างเธอนะคาริน"
L31_1.m_Talk_THA = L32_1
L32_1 = "Heh heh heh. Chúc may mắn vượt qua mọi khó khăn khi không có tôi bên cạnh, Karin nhé."
L31_1.m_Talk_VTN = L32_1
L32_1 = "嘿嘿嘿，我不在的这段时间就辛苦你了，卡琳~"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Hehehe. Viel Glück mit all dem Ärger und den Strapazen ohne mich an deiner Seite, Karin."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Hé hé hé. Bonne chance sans moi à vos côtés, Karin."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 31622
L32_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "이번 기회에 카린 양이 저의 소중함을 좀 깨달으셨으면 좋겠네요~"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L32_1.m_bTalkCenterFadeIn = true
L33_1 = "これを機に、カリンさんが私のありがたみに気づくといいな～"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I hope you realize my worth while I'm away!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "希望卡琳也能趁這個機會發現到我的珍貴～"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ฉันหวังว่าเธอจะคิดถึงคุณค่าของฉันบ้างขณะที่ฉันไม่อยู่ที่โลกนั้น!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tôi hy vọng cô nhận ra giá trị của tôi khi tôi đi vắng!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "希望卡琳能借此机会领悟到我的珍贵~"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ich hoffe, du nutzt die Gelegenheit und erkennst endlich mal, was ich wert bin, Karin!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "J'espère que vous réaliserez à quel point je compte, pendant mon absence !"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
