L34_1 = "……では、これで！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Now then... Bye!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "……那就，拜拜囉！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เอาล่ะ... บาย บาย โลกอดีตนั้น!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Giờ thì... Tạm biệt!"
