L34_1 = "那就……挥爪！先说拜拜啦！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Also dann ... Tschüss!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Sur ce... Au revoir !"
