L41_1 = "BATTLE_NORMAL_01"
L40_1.m_StartBGMFileName = L41_1
L41_1 = "저기 좀 봐!! 아카데미의 명물 고양이, 검은 누아르 네로 블랙 3세야!!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "あれを見て！！　アカデミー名物の猫、黒のノワール・ネロ・ブラック3世よ！！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Look! It's the Academy's famous cat, Dark Noir Nero Black III!"
L40_1.m_Talk_ENG = L41_1
L41_1 = "你們看！是學院的院貓，黑嚕嚕尼洛三世！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ดูสิ! นั่นคือแมวชื่อดังของสถาบัน ดาร์กนัวร์ เนโร แบล็ค!"
L40_1.m_Talk_THA = L41_1
L41_1 = "Nhìn kìa! Đó là con mèo nổi tiếng của Học viện, Dark Noir Nero Black III!"
L40_1.m_Talk_VTN = L41_1
L41_1 = "你们看！是学院的风云猫，黑色努亚尔尼洛三世！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Schau mal! Es ist die berühmte Katze der Akademie, Dark Noir Nero Black III.!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Regarde ! C'est le célèbre chat de l'Académie, Dark Noir Nero Black III !"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 31622
L41_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L41_1.m_bWaitClick = true
