L42_1 = "m_BGCrash"
L41_1[L42_1] = 20
L42_1 = "m_fBGCrashTime"
L43_1 = 0.5
L41_1[L42_1] = L43_1
L42_1 = "고양이가 미적분을 할 수 있다는 게 사실이야? 개인 SNS도 운영한다고 하던데?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "猫なのに微分積分が解けるって本当？　個人SNSもやってるらしいよ？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Is it true that the cat can solve calculus problems? It also has its own social media account!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "聽說貓咪會微積分，是真的嗎？而且還有私人社群平台？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "จริงหรือที่แมวจะสามารถแก้ปัญหาแคลคูลัสได้? แล้วก็มีบัญชีโซเชียลมีเดียเป็นของตัวเองด้วย!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Có đúng là con mèo có thể giải được các phép tính không? Nó còn có tài khoản trang media riêng nữa!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "听说猫咪会微积分，是真的吗？而且还有私人SNS？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Stimmt es, dass die Katze Rechenaufgaben lösen kann? Sie hat sogar einen eigenen Account in den sozialen Netzwerken!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "C'est vrai que ce chat peut résoudre des problèmes de maths ? On raconte même qu'il a son propre compte sur les réseaux sociaux !"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 31622
