L44_1 = 0.5
L42_1[L43_1] = L44_1
L43_1 = "소문으로는 자고 있는 여고생의 품 속에서 발견될 수도 있고, 발견되지 않을 수도 있대!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "噂によると、寝ている女子高生の胸の中で発見されることもあるとか、ないとか！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Rumors say it may or may not be found in the arms of a sleeping girl!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "聽說，偶爾還可以在睡著的女高中生懷裡發現牠！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ข่าวลือว่าอาจจะพบเจ้าแมวหรือปล่าวที่นอนในอ้อมแขนของเด็กสาวที่นอนหลับ!"
L42_1.m_Talk_THA = L43_1
L43_1 = "Nghe đồn nó có thể được thấy trong vòng tay của cô gái đang ngủ á!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "据传，偶尔可以在睡着的女高中生怀里发现！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Gerüchten zufolge könnte sie möglicherweise in den Armen eines schlafenden Mädchens gefunden werden oder auch nicht!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Les rumeurs racontent qu'on peut parfois le trouver dans les bras d'une fille endormie !"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@143#Talk"
