L45_1 = 0.5
L43_1[L44_1] = L45_1
L44_1 = "그 뿐만이 아니야, 카운터와 싸워 이겼다는 소문도 있다고!?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "それだけじゃないよ、カウンターと戦って勝ったっていう噂もあるんだって！！"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I've even heard a rumor about it beating a Counter!"
L43_1.m_Talk_ENG = L44_1
L44_1 = "而且不僅如此，聽說牠還打贏制裁者欸？！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฉันเคยได้ยินข่าวลือว่ามันเอาชนะเคาน์เตอร์ได้ด้วย!"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi còn nghe tin đồn là nó có thể đánh bại Counter!"
L43_1.m_Talk_VTN = L44_1
L44_1 = "而且不仅如此，听说它还打赢了制裁者？！"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich habe sogar ein Gerücht gehört, dass sie einen Counter besiegt hat!"
L43_1.m_Talk_DEU = L44_1
L44_1 = "J'ai même entendu dire qu'il aurait gagné contre un Counter !"
L43_1.m_Talk_FRA = L44_1
