L5_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 31622
