L5_1 = "UNIT_DESPAIR"
L4_1.m_Face = L5_1
L4_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L4_1.m_Pos = "L"
L4_1.m_bCharPinup = true
L5_1 = "(이런, 어쩌다 어쩌다 이렇게 되어버렸을까나?)"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "(まいったな、どうしてこんなことになったんだろう？)"
L4_1.m_Talk_JPN = L5_1
L5_1 = "(Well, how did I end up like this?)"
L4_1.m_Talk_ENG = L5_1
L5_1 = "（呃，怎麼會變成現在這種情況？）"
L4_1.m_Talk_TWN = L5_1
L5_1 = "(แล้วฉันกลายเป็นแบบนี้ได้ยังไงกัน?)"
L4_1.m_Talk_THA = L5_1
L5_1 = "(Chà, sao tôi lại thành ra thế này nhỉ?)"
L4_1.m_Talk_VTN = L5_1
L5_1 = "（呃，怎么会变成现在这种情况呢？）"
L4_1.m_Talk_SCN = L5_1
L5_1 = "(Verdammt, wie ist es nur so gekommen?)"
L4_1.m_Talk_DEU = L5_1
L5_1 = "(Je me demande bien comment je m'y suis prise pour finir comme ça...)"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 31622
L5_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L5_1.m_Pos = "L"
L5_1.m_bCharPinup = true
L6_1 = "(이건 좀 곤란하네. 너무 인기 있는 것도 생각보다 부담스럽잖아?)"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "(これは少々まずいことになったな。人気がありすぎるのも案外厄介だね？)"
L5_1.m_Talk_JPN = L6_1
L6_1 = "(This is too much. It's too pressuring to be so popular.)"
L5_1.m_Talk_ENG = L6_1
L6_1 = "（這有點尷尬呢，太受歡迎比想像中要累呢？）"
L5_1.m_Talk_TWN = L6_1
L6_1 = "(นี่มันมากเกินไปแล้ว มากดดันกันเกินไปขนาดนี้เลยหรอ)"
L5_1.m_Talk_THA = L6_1
L6_1 = "(Điều này thật quá đáng. Trở nên nổi tiếng như vậy thật quá áp lực.)"
L5_1.m_Talk_VTN = L6_1
L6_1 = "（这有点让我为难啊。太受欢迎，比想象中要累呢？）"
L5_1.m_Talk_SCN = L6_1
L6_1 = "(Das ist zu viel. Es ist zu anstrengend, so beliebt zu sein.)"
L5_1.m_Talk_DEU = L6_1
L6_1 = "(C'est trop stressant d'être populaire.)"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
