L17_1 = "무슨 헛소리야? 우린 인간한테 관심 없어!"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "何言っているの？　人間には興味ないわよ！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "What are you talking about? We're not interested in humans!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "你在胡說什麼？我們對人類不感興趣！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "เธอกำลังพูดถึงอะไรน่ะ? เราไม่สนใจมนุษย์สักหน่อย!"
L16_1.m_Talk_THA = L17_1
L17_1 = "Cô bị làm sao vậy? Chúng tôi không quan tâm đến con người!"
L16_1.m_Talk_VTN = L17_1
L17_1 = "你在胡说什么？我们对人类不感兴趣！"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Wovon redest du? Wir interessieren uns nicht für Menschen!"
L16_1.m_Talk_DEU = L17_1
