L19_1 = 0.5
L17_1[L18_1] = L19_1
L18_1 = "우린 푹신푹신한 털을 가진 진짜 고양이를 원한다고! 고양이 흉내를 내는 이상한 여자애가 아니라!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "私たちはふわふわな毛を持つ本物の猫を求めているの！　猫真似をする変な女の子じゃなくて！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "We want a real cat, with soft fur! Not a creepy girl who acts like a cat!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "我們要的是毛茸茸的真貓！不是模仿貓咪的奇怪女生！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เราต้องการแมวตัวจริงที่มีขนนุ่มๆ! ไม่ใช่สาวที่น่าขนลุกและทำตัวเหมือนแมว!"
L17_1.m_Talk_THA = L18_1
L18_1 = "Chúng tôi muốn một con mèo thật với bộ lông mềm mại! Không phải là một cô gái đáng sợ hành động như một con mèo!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "我们要的是毛茸茸的真猫！不是模仿猫咪的奇怪女孩！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Wir wollen eine echte Katze mit weichem Fell! Kein gruseliges Mädchen, das sich lediglich wie eine Katze verhält!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Ce qu'on veut, c'est un vrai chat, avec une fourrure douce ! Pas une fille chelou qui se prend pour un chat !"
L17_1.m_Talk_FRA = L18_1
