L23_1 = "あそこよ！　あっちに逃げてくわ！！"
L22_1.m_Talk_JPN = L23_1
L23_1 = "There it is! It's running that way!"
L22_1.m_Talk_ENG = L23_1
L23_1 = "在那裡！牠跑到那裡了！"
L22_1.m_Talk_TWN = L23_1
L23_1 = "นั่นมัน! มันวิ่งไปทางนั้นแล้ว!"
L22_1.m_Talk_THA = L23_1
L23_1 = "Nó đây rồi! Nó đang chạy hướng đó!"
L22_1.m_Talk_VTN = L23_1
L23_1 = "在那儿！它跑到那里了！"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Da ist sie! Sie läuft dort entlang!"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Le voilà ! Il s'enfuit par là !"
