L26_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@175#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 31622
L25_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_IDLE"
L25_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L25_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L25_1.m_Pos = "L"
L25_1.m_bCharPinup = true
L26_1 = "(시간을 벌어줘서 고마워, 냥이엘. 이 은혜는 나중에 육포로 갚을게.)"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "(時間を稼いでくれてありがとう、ニャイエル。この恩はジャーキーで返すからね。)"
L25_1.m_Talk_JPN = L26_1
L26_1 = "(Thanks for stalling, Nya-iel. I'll pay you back with beef jerky later.)"
L25_1.m_Talk_ENG = L26_1
L26_1 = "（謝謝你為我爭取時間，喵爾，我以後會用肉泥報答你的。）"
L25_1.m_Talk_TWN = L26_1
L26_1 = "(ขอบคุณที่ขัดขวางนะ ไอเอล ฉันจะตอบแทนเธอด้วยเนื้อแดดเดียวในภายหลังนะ)"
L25_1.m_Talk_THA = L26_1
L26_1 = "(Cảm ơn vì đã chặn họ, Nya-iel. Tôi sẽ trả cô bằng thịt bò khô sau.)"
L25_1.m_Talk_VTN = L26_1
L26_1 = "（谢谢你为我争取了时间，喵奈尔。我以后会拿肉脯报答你的。）"
L25_1.m_Talk_SCN = L26_1
L26_1 = "(Danke fürs Hinhalten, Miau-Naielle. Ich werde mich später mit Trockenfleisch bei dir dafür revanchieren.)"
L25_1.m_Talk_DEU = L26_1
L26_1 = "(Merci de m'avoir fait gagner du temps, Niaouelle. Je te revaudrai ça avec une tranche de bœuf séchée plus tard.)"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 31622
L26_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "UNIT_PRIDE"
L26_1.m_Face = L27_1
L26_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L26_1.m_Pos = "L"
L26_1.m_bCharPinup = true
L27_1 = "(좋아, 일단 가장 안전한 학생회장실로 도망쳐 볼까?)"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "(よし、とりあえず一番安全な生徒会長室に逃げよう。)"
L26_1.m_Talk_JPN = L27_1
L27_1 = "(Now, let's run to the safe and sound Student President's office.)"
L26_1.m_Talk_ENG = L27_1
L27_1 = "（很好，先逃到最安全的學生會辦公室吧！）"
L26_1.m_Talk_TWN = L27_1
L27_1 = "(ตอนนี้ ขอวิ่งไปที่ห้องทำงานของประธานนักเรียนเพื่อหลบก่อน)"
L26_1.m_Talk_THA = L27_1
L27_1 = "(Bây giờ, hãy chạy đến văn phòng Chủ Tịch Hội Học Sinh an toàn và bình yên nào.)"
L26_1.m_Talk_VTN = L27_1
L27_1 = "（很好，先逃到最安全的学生会长室吧！）"
L26_1.m_Talk_SCN = L27_1
L27_1 = "(Jetzt aber erst mal schnell zum sicheren Büro der Schülerpräsidentin.)"
L26_1.m_Talk_DEU = L27_1
L27_1 = "(Bien, je devrais me diriger vers le bureau de la présidente, c'est l'endroit le plus sûr !)"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
