L32_1 = "UNIT_DESPAIR"
L31_1.m_Face = L32_1
L31_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "이런 일이 일어나다니…… 미안해요, 네로 란체스터 3세. 역시 제가 너무 안일했군요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "こんなことが起きるなんて……ごめんなさい、ネロ・ランチェスター3世。私が愚かでした。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Oh dear... I'm so sorry, Nero Lanchester III. I was too naive."
L31_1.m_Talk_ENG = L32_1
L32_1 = "竟然發生這種事……對不起，尼洛·蘭賈斯特三世，是我太大意了。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "โอ้ที่รัก... ฉันขอโทษจริงๆ นีโร แลนเชสเตอร์ที่ III ฉันมันไร้เดียงสาเกินไป"
L31_1.m_Talk_THA = L32_1
L32_1 = "Ôi trời... Chị rất xin lỗi, Nero Lanchester III. Chị đã quá ngây thơ."
L31_1.m_Talk_VTN = L32_1
L32_1 = "竟然发生了这种事……对不起，尼洛·兰切斯特三世。是我太安逸了。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Oh je ... Tut mir so leid, Nero Lanchester III. Ich war einfach zu naiv."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Oh mon Dieu... Je suis vraiment désolée, Nero Lanchester III. J'ai été trop naïve..."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
