L34_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 31622
L33_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_LAUGH"
L33_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L33_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L33_1.m_Pos = "L"
L33_1.m_bCharPinup = true
L34_1 = "(그렇지, 역시 학생회장님이라면, 역시 도와줄 거라고 생각했다고요.)"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "(うん、生徒会長なら、私を助けてくれるって思っていましたよ。)"
L33_1.m_Talk_JPN = L34_1
L34_1 = "(I knew it. Of course the Student President would help me.)"
L33_1.m_Talk_ENG = L34_1
L34_1 = "（很好，不愧是學生會長，我就知道你會幫我。）"
L33_1.m_Talk_TWN = L34_1
L34_1 = "(ฉันรู้ แน่นอนว่าประธานนักเรียนจะต้องช่วยฉัน)"
L33_1.m_Talk_THA = L34_1
L34_1 = "(Tôi biết ngay mà. Tất nhiên Chủ Tịch sẽ giúp tôi.)"
L33_1.m_Talk_VTN = L34_1
L34_1 = "（就是这样，不愧是学生会长，我就知道你会帮我。）"
L33_1.m_Talk_SCN = L34_1
L34_1 = "(Ich wusste es doch. Natürlich würde mir die Schülerpräsidentin helfen.)"
L33_1.m_Talk_DEU = L34_1
L34_1 = "(J'étais sûre que la présidente des élèves m'aiderait.)"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
