L37_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 31622
L36_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "UNIT_DESPAIR"
L36_1.m_Face = L37_1
L36_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L36_1.m_Pos = "R"
L37_1 = "아카데미의 마스코트인 네로 란체스터 3세의 행복을 위해……"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "アカデミーのマスコットであるネロ・ランチェスター3世の幸せのために……"
L36_1.m_Talk_JPN = L37_1
L37_1 = "For the happiness of our Academy's mascot, Nero Lanchester III..."
L36_1.m_Talk_ENG = L37_1
L37_1 = "我希望學院吉祥物尼洛·蘭賈斯特三世能夠在學院幸福生活……"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เพื่อความสุขของมาสคอตแห่งสถาบัน เนโร แลนเชสเตอร์ III..."
L36_1.m_Talk_THA = L37_1
L37_1 = "Vì hạnh phúc của linh vật Học viện của chúng ta, Nero Lanchester III..."
L36_1.m_Talk_VTN = L37_1
L37_1 = "为了学院吉祥物尼洛·兰切斯特三世的幸福……"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Zum Wohle des Maskottchens unserer Akademie, Nero Lanchester III. ..."
L36_1.m_Talk_DEU = L37_1
L37_1 = "C'est pour ton bonheur, Nero Lanchester III, la mascotte de l'Académie..."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 31622
L37_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L37_1.m_Pos = "R"
L38_1 = "그동안 네로 란체스터가 아카데미 내부를 자유롭게 돌아다닐 수 있도록 조치해 두었지만."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "これまでネロ・ランチェスターがアカデミー内部を自由に動き回れるようにしておきましたが。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I've made it so that you could roam the campus freely, but."
L37_1.m_Talk_ENG = L38_1
L38_1 = "所以有提前做好措施，方便你在學院自由走動。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ฉันทำให้เธอเพื่อจพได้ท่องไปในสถาบันได้อย่างอิสระ แต่"
L37_1.m_Talk_THA = L38_1
L38_1 = "Chị đã để em có thể tự do đi lại trong khuôn viên trường, nhưng."
L37_1.m_Talk_VTN = L38_1
L38_1 = "我提前做好了措施，方便你在学院自由走动。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Habe ich dich bis jetzt frei in der Akademie herumlaufen lassen, aber ..."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Que j'ai fait en sorte que tu puisses vagabonder librement sur le campus, mais..."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 31622
L38_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L38_1.m_Pos = "R"
L39_1 = "오히려 그게 외부인의 무단 침입이라는 결과를 만들어냈군요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "それがむしろ外部者の無断侵入という結果を生んでしまったのですね。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "It has led to outsiders trespassing on our campus."
L38_1.m_Talk_ENG = L39_1
L39_1 = "但反而造成外人擅自闖入。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "มันทำให้คนนอกบุกรุกเข้ามาในสถาบันของเราด้วย"
L38_1.m_Talk_THA = L39_1
L39_1 = "Nó đã dẫn đến việc người ngoài xâm phạm vào khuôn viên trường của chúng ta."
L38_1.m_Talk_VTN = L39_1
L39_1 = "但我的举措反而造成了外人擅自闯入的结果。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Es hat leider dazu geführt, dass Außenstehende unsere Akademie unbefugt betreten haben."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Cela a conduit à l'intrusion d'étrangers sur notre campus."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 31622
L39_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L39_1.m_Pos = "R"
L40_1 = "분명, 네로 란체스터 3세도 불안했죠?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "きっと、ネロ・ランチェスター3世も不安でしたよね？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "And I'm sure it made you uncomfortable."
L39_1.m_Talk_ENG = L40_1
L40_1 = "尼洛·蘭賈斯特三世你是不是很害怕？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "และฉันแน่ใจว่ามันทำให้เธอไม่สบายใจ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Và chị chắc chắn điều đó làm em khó chịu."
L39_1.m_Talk_VTN = L40_1
L40_1 = "尼洛·兰切斯特三世，其实你也很不安吧？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Und ich bin mir sicher, es hat dir Unbehagen bereitet. Nicht wahr, Nero Lanchester III.?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "J'imagine que cela t'a mis dans l'embarras."
L39_1.m_Talk_FRA = L40_1
