L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 31622
L41_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L41_1.m_Pos = "R"
L42_1 = "하지만 걱정하지 마세요. 네로 란체스터 3세."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "でも心配しないでください。ネロ・ランチェスター3世。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "But you needn't worry anymore, Nero Lanchester III."
L41_1.m_Talk_ENG = L42_1
L42_1 = "不用擔心，尼洛·蘭賈斯特三世。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "แต่เธอไม่จำเป็นต้องกังวลอีกต่อไป เนโร แลนเชสเตอร์ III"
L41_1.m_Talk_THA = L42_1
L42_1 = "Nhưng em không cần phải lo lắng nữa, Nero Lanchester III."
L41_1.m_Talk_VTN = L42_1
L42_1 = "但不用担心，尼洛·兰切斯特三世。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Aber du brauchst dir keine Sorgen mehr zu machen, Nero Lanchester III."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Mais tu n'as plus besoin de t'inquiéter, Nero Lanchester III."
L41_1.m_Talk_FRA = L42_1
