L45_1 = 194
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 31622
L44_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
