L45_1 = "BLACK"
L44_1.m_BGFileName = L45_1
L45_1 = "UNIT_PRIDE"
L44_1.m_Face = L45_1
L45_1 = "CUTSCENE_TALK_02"
L44_1.m_StartBGMFileName = L45_1
L44_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "<color=#ffd34c>이제부터 이 방이 네로 란체스터 3세의 보금자리니까요.</color>"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "<color=#ffd34c>これからはこの部屋がネロ・ランチェスター3世の部屋です。</color>"
L44_1.m_Talk_JPN = L45_1
L45_1 = "<color=#ffd34c>This room will be your new home.</color>"
L44_1.m_Talk_ENG = L45_1
L45_1 = "<color=#ffd34c>從現在開始，這個房間就是尼洛·蘭賈斯特三世的小窩。</color>"
L44_1.m_Talk_TWN = L45_1
L45_1 = "<color=#ffd34c>ห้องนี้จะเป็นบ้านใหม่ของเธอ</color>"
L44_1.m_Talk_THA = L45_1
L45_1 = "<color=#ffd34c>Căn phòng này sẽ là ngôi nhà mới của em.</color>"
L44_1.m_Talk_VTN = L45_1
L45_1 = "<color=#ffd34c>从现在开始这个房间就是尼洛·兰切斯特三世的小窝了。</color>"
L44_1.m_Talk_SCN = L45_1
L45_1 = "<color=#ffd34c>Dieser Raum wird von nun an dein neues Zuhause sein.</color>"
L44_1.m_Talk_DEU = L45_1
L45_1 = "<color=#ffd34c>Cette pièce sera ta nouvelle maison.</color>"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@195#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 195
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 31622
L45_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L45_1.m_Pos = "C"
L46_1 = "<color=#ffd34c>앞으로는 이 방을 나가지 말도록 해요.</color>"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "<color=#ffd34c>これからはこの部屋から出ていかないようにしてくださいね。</color>"
L45_1.m_Talk_JPN = L46_1
L46_1 = "<color=#ffd34c>From now on, you mustn't leave this room.</color>"
L45_1.m_Talk_ENG = L46_1
L46_1 = "<color=#ffd34c>以後就不要離開這個房間囉。</color>"
L45_1.m_Talk_TWN = L46_1
L46_1 = "<color=#ffd34c>จากนี้ไปห้ามออกจากห้องนี้นะ</color>"
L45_1.m_Talk_THA = L46_1
L46_1 = "<color=#ffd34c>Từ giờ trở đi, em không được rời khỏi phòng này.</color>"
L45_1.m_Talk_VTN = L46_1
L46_1 = "<color=#ffd34c>以后就不要离开这个房间了。</color>"
L45_1.m_Talk_SCN = L46_1
L46_1 = "<color=#ffd34c>Von jetzt an darfst du diesen Raum nicht mehr verlassen.</color>"
L45_1.m_Talk_DEU = L46_1
L46_1 = "<color=#ffd34c>À partir de maintenant, tu ne dois plus quitter cette pièce.</color>"
L45_1.m_Talk_FRA = L46_1
