L50_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 31622
L49_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L49_1.m_bWaitClick = true
