L49_1.m_Face = "UNIT_IDLE"
L49_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L49_1.m_Pos = "R"
L50_1 = "그도 그럴 것이…… 원래 고양이는 영역동물이잖아요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "確かに思えば……もともと猫は縄張りを大事にする動物です。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "After all... cats are territorial animals."
L49_1.m_Talk_ENG = L50_1
L50_1 = "畢竟……貓本來就是有領地意識的動物。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "สุดแล้ว... แมวก็เป็นสัตว์ในดินแดนกักขัง"
L49_1.m_Talk_THA = L50_1
L50_1 = "Suy cho cùng... mèo là động vật có lãnh thổ."
L49_1.m_Talk_VTN = L50_1
L50_1 = "毕竟……猫本来就是有领地意识的动物。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Schließlich ... sind Katzen von Natur aus territoriale Tiere."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Après tout... Les chats sont des animaux territoriaux."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@200#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 200
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 31622
L50_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_Face = "UNIT_LAUGH"
L50_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L50_1.m_Pos = "R"
L51_1 = "그러니까, 네로 란체스터 3세는 산책을 할 필요가 없었던 거죠."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "つまり、ネロ・ランチェスター3世には散歩は必要なかった。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Hence, it was never necessary to let you roam free in the first place."
L50_1.m_Talk_ENG = L51_1
L51_1 = "從一開始，讓你隨意在外面遊蕩就是不對的。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ทำไมต้องปล่อยให้เธอท่องไปอย่างอิสระตั้งแต่แรกนะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Do đó, ngay từ đầu việc để em tự do đi lang thang chưa bao giờ là cần thiết."
L50_1.m_Talk_VTN = L51_1
L51_1 = "从一开始，让你随意在外面游荡就是不对的。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Daher war es von Anfang an nicht notwendig, dich überhaupt frei herumlaufen zu lassen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Par conséquent, il n'a jamais été nécessaire de te laisser errer librement."
L50_1.m_Talk_FRA = L51_1
