L3_1 = "UNIT_PRIDE"
L2_1.m_Face = L3_1
L2_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L2_1.m_Pos = "R"
L3_1 = "걱정 마세요, 그 대신 1일 3간식과 털손질, 놀아주기, 자장가 불러주기를 제공해 드릴테니."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "心配しないでください。その代わり1日3回のおやつと、毛の手入れ、お遊び、子守唄を歌う、これらを提供しますから。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Don't worry. Instead, I'll provide you with three treats a day, fur maintenance, play time, and a lullaby before bed."
L2_1.m_Talk_ENG = L3_1
L3_1 = "不用擔心，我還會給你一日三餐，給你梳毛、陪你玩，唱搖籃曲。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ไม่ต้องกังวล แต่ฉันจะให้ขนมเธอสามครั้งต่อวัน พร้อมการดูแลรักษาขน มีเวลาเล่น และมีเพลงกล่อมก่อนนอน"
L2_1.m_Talk_THA = L3_1
L3_1 = "Đừng lo. Nên là chị sẽ cho em ba bữa mỗi ngày, chải lông, thời gian chơi và một bài hát ru trước khi đi ngủ."
L2_1.m_Talk_VTN = L3_1
L3_1 = "不用担心，我还会给你一日三餐，给你梳毛、陪你玩、唱摇篮曲。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Keine Sorge. Stattdessen werde ich dir drei Leckerlis pro Tag geben, dein Fell pflegen, mit dir spielen und dir ein Schlaflied vor dem Einschlafen singen."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Ne t'inquiète pas. Au lieu de cela, je te fournirai trois friandises par jour, je prendrai soin de ta fourrure, je jouerai avec toi et te chanterai une berceuse pour t'endormir."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
