L6_1 = "고집 부려도 소용없답니다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "意地を張っても仕方ありません。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Making a fuss won't do anything."
L5_1.m_Talk_ENG = L6_1
L6_1 = "就算你和我頂嘴也沒用。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "วุ่นวายไปก็ไม่ได้อะไร"
L5_1.m_Talk_THA = L6_1
L6_1 = "Làm ầm lên sẽ không có tác dụng gì đâu!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "就算你和我犟也没用。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Es bringt nichts, mit mir darüber zu diskutieren."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Faire des histoires ne changera rien."
L5_1.m_Talk_FRA = L6_1
