L6_1.m_Crash = 10
L7_1 = "이게 다 네로 란체스터 3세의 행복을 위한 거니까요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "これも全て、ネロ・ランチェスター3世の幸せのためですから。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "This is all for the happiness of Nero Lanchester III."
L6_1.m_Talk_ENG = L7_1
L7_1 = "我這都是再為尼洛·蘭賈斯特三世著想。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ทั้งหมดนี้เพื่อความสุขของ เนโร แลนเชสเตอร์ III"
L6_1.m_Talk_THA = L7_1
L7_1 = "Tất cả đều vì hạnh phúc của Nero Lanchester III."
L6_1.m_Talk_VTN = L7_1
L7_1 = "这都是为了尼洛·兰切斯特三世的幸福。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Das ist nur zu deinem Wohl Nero Lanchester III."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Tout cela est pour ton bien, Nero Lanchester III."
L6_1.m_Talk_FRA = L7_1
