L9_1 = "UNIT_DESPAIR"
L8_1.m_Face = L9_1
L8_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L8_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L8_1.m_Pos = "L"
L8_1.m_bCharPinup = true
L9_1 = "(하하, 틀렸어 전혀 말이 안 통해.)"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "(ハハ、ダメだ、全然話が通じない。)"
L8_1.m_Talk_JPN = L9_1
L9_1 = "(Ha hah, I'm screwed. I can't get through to her.)"
L8_1.m_Talk_ENG = L9_1
L9_1 = "（哈哈，糟糕，根本說不通。）"
L8_1.m_Talk_TWN = L9_1
L9_1 = "(ฮ่า ฮ่า มันบ้าไปแล้ว ฉันวิ่งหนีผ่านเธอไปไม่ได้)"
L8_1.m_Talk_THA = L9_1
L9_1 = "(Ha ha, mình xong đời rồi. Mình không thể vượt qua được cô ấy.)"
L8_1.m_Talk_VTN = L9_1
L9_1 = "（哈哈，完蛋了，根本说不通。）"
L8_1.m_Talk_SCN = L9_1
L9_1 = "(Haha, ich stecke in der Klemme. Sie versteht kein Wort.)"
L8_1.m_Talk_DEU = L9_1
L9_1 = "(Ha ha, c'est fichu. Je n'arrive pas à communiquer avec elle.)"
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@209#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 209
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 31622
L9_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L9_1.m_Pos = "L"
L9_1.m_bCharPinup = true
L10_1 = "(설마, 믿었던 학생회장님에게 감금당할 줄이야.)"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "(まさか、信じていた生徒会長に監禁されるとは。)"
L9_1.m_Talk_JPN = L10_1
L10_1 = "(I trusted the Student President. I didn't think she'd lock me up.)"
L9_1.m_Talk_ENG = L10_1
L10_1 = "（沒想到我會被信任的學生會長監禁。）"
L9_1.m_Talk_TWN = L10_1
L10_1 = "(ฉันเชื่อใจประธานนักเรียน แต่ฉันไม่คิดว่าเธอจะขังฉันไว้)"
L9_1.m_Talk_THA = L10_1
L10_1 = "(Mình đã tin tưởng Chủ Tịch. Không ngờ cô ấy sẽ nhốt mình lại.)"
L9_1.m_Talk_VTN = L10_1
L10_1 = "（没想到我会被信任的学生会长监禁。）"
L9_1.m_Talk_SCN = L10_1
L10_1 = "(Ich habe der Schülerpräsidentin vertraut. Ich hätte nicht gedacht, dass sie mich hier einsperren würde.)"
L9_1.m_Talk_DEU = L10_1
L10_1 = "(Je faisais confiance à la présidente... Je ne pensais pas qu'elle allait m'enfermer.)"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
