L10_1.m_Pos = "L"
L10_1.m_bCharPinup = true
L11_1 = "(뭐, 말이 안 통하니…… 어쩔 수 없으려나.)"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "(まぁ、話が通じないなら……仕方ないか。)"
L10_1.m_Talk_JPN = L11_1
L11_1 = "(Well, since I can't speak... I guess there's no other choice.)"
L10_1.m_Talk_ENG = L11_1
L11_1 = "（嘖，也沒辦法說話……還有什麼辦法嗎？）"
L10_1.m_Talk_TWN = L11_1
L11_1 = "(เพราะว่าฉันพูดไม่ได้... นั้นไม่มีทางเลือกอื่นแล้ว)"
L10_1.m_Talk_THA = L11_1
L11_1 = "(Chà, vì mình không thể nói... nên chắc không còn lựa chọn nào khác.)"
L10_1.m_Talk_VTN = L11_1
L11_1 = "（算了，也没办法说话……应该没其他办法了吧。）"
L10_1.m_Talk_SCN = L11_1
L11_1 = "(Nun, da ich nicht sprechen kann ... habe ich wohl keine andere Wahl.)"
L10_1.m_Talk_DEU = L11_1
L11_1 = "(Eh bien, puisque je ne peux pas parler... Je suppose qu'il n'y a pas d'autre choix.)"
L10_1.m_Talk_FRA = L11_1
