L13_1.m_Talk_ENG = L14_1
L14_1 = "等，等等！尼洛·蘭賈斯特！你在做什麼……！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ดะ-เดี๋ยวก่อน! เนโร แลนเชสเตอร์! เธอจะทำไร...!"
L13_1.m_Talk_THA = L14_1
L14_1 = "Đ-đợi đã! Nero Lanchester! Em đang làm gì...!"
L13_1.m_Talk_VTN = L14_1
L14_1 = "等、等等！尼洛·兰切斯特！你在做什么……！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "W-warte! Nero Lanchester! Was machst du denn ...?!"
L13_1.m_Talk_DEU = L14_1
