L20_1.m_bCharPinup = true
L21_1 = "(생각보다 고양이의 삶도 그리 순탄지 않네…….)"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "(猫として生きるのも、案外楽じゃないんだな……)"
L20_1.m_Talk_JPN = L21_1
L21_1 = "(Living as a cat isn't as easy as I thought...)"
L20_1.m_Talk_ENG = L21_1
L21_1 = "（看來貓咪的生活也沒有我想得那麼順利呢……）"
L20_1.m_Talk_TWN = L21_1
L21_1 = "(การใช้ชีวิตแบบแมวนั้นมันไม่ง่ายอย่างที่คิดเลย...)"
L20_1.m_Talk_THA = L21_1
L21_1 = "(Sống như một con mèo không hề dễ dàng như mình nghĩ...)"
L20_1.m_Talk_VTN = L21_1
L21_1 = "（看来猫咪的生活，也没有我想得那么顺利啊……）"
L20_1.m_Talk_SCN = L21_1
L21_1 = "(Als Katze zu leben ist nicht so einfach, wie ich gedacht hatte ...)"
L20_1.m_Talk_DEU = L21_1
L21_1 = "(Vivre en tant que chat n'est pas aussi facile que je le pensais...)"
L20_1.m_Talk_FRA = L21_1
