L21_1.m_bCharPinup = true
L22_1 = "(당분간 노숙을 해야 하나?)"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "(しばらくは野宿か？)"
L21_1.m_Talk_JPN = L22_1
L22_1 = "(Looks like I have to sleep on the streets for a while."
L21_1.m_Talk_ENG = L22_1
L22_1 = "（暫時要在街頭流浪嗎？）"
L21_1.m_Talk_TWN = L22_1
L22_1 = "(เหมือนจะต้องนอนข้างถนนสักพัก.."
L21_1.m_Talk_THA = L22_1
L22_1 = "(Có vẻ như mình phải ngủ ngoài đường một lúc rồi."
L21_1.m_Talk_VTN = L22_1
L22_1 = "（难道要开始流浪了吗？）"
L21_1.m_Talk_SCN = L22_1
L22_1 = "(Sieht aus, als müsste ich eine Weile auf der Straße schlafen.)"
L21_1.m_Talk_DEU = L22_1
L22_1 = "(On dirait que je vais devoir dormir dans la rue pendant un moment.)"
L21_1.m_Talk_FRA = L22_1
