L22_1.m_Pos = "L"
L22_1.m_bCharPinup = true
L23_1 = "(뭐, 원래 세계에서도 노숙은 익숙하니까. 별 상관은 없겠지.)"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "(まぁ、元の世界でも野宿はよくしていたし。いいか。)"
L22_1.m_Talk_JPN = L23_1
L23_1 = "(Well, I'm used to sleeping on the streets in my home world. It won't be a big deal.)"
L22_1.m_Talk_ENG = L23_1
L23_1 = "（反正在原本的世界我也很習慣流浪，無所謂。）"
L22_1.m_Talk_TWN = L23_1
L23_1 = "(ฉันชินกับการนอนข้างถนนในโลกอดีตอยู่แล้ว มันคงไม่ใช่ปัญหาอะไร)"
L22_1.m_Talk_THA = L23_1
L23_1 = "(Chà, mình đã quen với việc ngủ ngoài đường ở thế giới quê nhà rồi. Sẽ không có vấn đề gì lớn đâu.)"
L22_1.m_Talk_VTN = L23_1
L23_1 = "（在原来的世界我也习惯流浪了，也没什么关系。）"
L22_1.m_Talk_SCN = L23_1
L23_1 = "(Nun, in meiner Heimatwelt bin ich es gewohnt, auf der Straße zu schlafen. Es ist also keine große Sache.)"
L22_1.m_Talk_DEU = L23_1
L23_1 = "(Après tout, j'ai l'habitude de dormir dans la rue dans mon monde d'origine. Ce ne sera pas un gros problème.)"
L22_1.m_Talk_FRA = L23_1
