L28_1 = "드디어 찾았네, 이 골치덩어리."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "やっと見つけたぞ、このヤンチャ猫。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I finally found you, you troublemaker."
L27_1.m_Talk_ENG = L28_1
L28_1 = "終於找到你了，你這個小搗蛋。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "เฮ ในที่สุดฉันก็พบเธอแล้ว เธอคนเจ้าปัญหา"
L27_1.m_Talk_THA = L28_1
L28_1 = "Cuối cùng ta đã tìm thấy mày, đồ gây rối."
L27_1.m_Talk_VTN = L28_1
L28_1 = "终于找到你了，你这个闯祸精。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ich habe dich endlich gefunden, du Unruhestifter."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Te voilà enfin, petit fauteur de troubles."
L27_1.m_Talk_FRA = L28_1
