L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L28_1.m_Crash = 20
L29_1 = "정어리 값이 올라서 다른 생선으로 바꾸자니까, 몰래 가출해버려?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "イワシが値上がりしたから他の魚に変えようとしたら、こっそり家出するなんて！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "I suggest switching to a different fish because sardines went up in price, and you run away from home?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "因為沙丁魚漲價要幫你換成其他魚，你就賭氣離家出走？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "แนะนำให้เปลี่ยนปลาชนิดอื่นเพราะปลาซาร์ดีนมันขึ้นราคาแล้ว นี่เธอหนีออกจากบ้านหรอ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Tao đề nghị chuyển sang một loại cá khác vì cá mòi tăng giá nên mày bỏ nhà đi?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "沙丁鱼涨价了，要给你换成其他鱼，你就赌气偷偷离家出走？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Ich schlage vor, auf einen anderen Fisch umzusteigen, weil der Preis für Sardinen gestiegen ist und du heimlich von zu Hause ausgerissen bist?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Tu t'enfuis juste parce que j'ai suggéré de changer ton poisson parce que le prix des sardines a augmenté ?"
L28_1.m_Talk_FRA = L29_1
