L49_1 = "我不知道你是故意來到這裡的，還是意外……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "อืม ฉันไม่แน่ใจว่าเธอจงใจมาที่นี่หรือบังเอิญมาอยู่ที่นี่ แต่..."
L48_1.m_Talk_THA = L49_1
L49_1 = "Tôi không chắc liệu cô cố ý hay vô tình đến đây, nhưng..."
L48_1.m_Talk_VTN = L49_1
L49_1 = "我不知道你是故意来到这里的，还是偶然卷进来的……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ich bin mir nicht sicher, ob du absichtlich hierhergekommen bist oder nur versehentlich hier gelandet bist, aber ..."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Je ne sais pas si tu es venue ici délibérément ou par accident, mais..."
L48_1.m_Talk_FRA = L49_1
