L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "R"
L50_1 = "이런 식으로 의식만 다른 차원으로 넘어오는 행위는 굉장히 위험해."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "こんなふうに意識だけが別次元に来るのは危険すぎる。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "It's very dangerous to cross dimensions only with your consciousness."
L49_1.m_Talk_ENG = L50_1
L50_1 = "像這樣只有意識來到其他次元是非常危險的行為。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "การข้ามมิติด้วยคำขอของเธอมัน อันตรายมาก"
L49_1.m_Talk_THA = L50_1
L50_1 = "Sẽ rất nguy hiểm nếu chỉ vượt qua các chiều không gian bằng ý thức của cô."
L49_1.m_Talk_VTN = L50_1
L50_1 = "像这样只有意识来到其他次元是非常危险的行为。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Es ist sehr gefährlich, Dimensionen nur mit dem Bewusstsein zu durchqueren."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Il est très dangereux de changer de dimension uniquement avec sa conscience."
L49_1.m_Talk_FRA = L50_1
