L4_1 = "아티팩트의 저주를 풀어줄 테니 얌전히 원래 세계로 돌아가."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "アーティファクトの呪いを解除してやるから、大人しく元の世界に戻れ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "I'll lift the Artifact's curse, so go back to your home world."
L3_1.m_Talk_ENG = L4_1
L4_1 = "我會幫你解開人造神器的詛咒，你還是乖乖回到原來的世界吧。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฉันจะช่วยถอนคำสาปของ อาร์ติแฟ็กต์ ให้ แล้วกลับไปโลกบ้านเกิดของเธอซะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Tôi sẽ hóa giải lời nguyền của Thần Khí, vậy nên hãy quay về thế giới quê hương của mình đi."
L3_1.m_Talk_VTN = L4_1
L4_1 = "我会帮你解开人造神器的诅咒，你还是乖乖回到原来的世界吧。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Ich werde den Fluch des Artefakts aufheben, also kehre in deine Heimatwelt zurück."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Je vais lever la malédiction de l'artefact et tu pourras retourner dans ton monde d'origine."
L3_1.m_Talk_FRA = L4_1
