L20_1 = "UNIT_DESPAIR"
L19_1.m_Face = L20_1
L19_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L19_1.m_Pos = "R"
L20_1 = "하, 하하. 원래 세계로 돌아온 건가?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "ハ、ハハ。元の世界に帰ってきたみたい？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Hah, ha ha. I guess I'm back at my home world."
L19_1.m_Talk_ENG = L20_1
L20_1 = "哈，哈哈。我回到原來的世界啦？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ฮ่า ฮ่า ฮ่า ฉันว่าฉันกลับมาที่โลกบ้านเกิดของฉันแล้วหล่ะ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Ha, ha ha. Có lẽ tôi đã trở về thế giới quê hương của mình."
L19_1.m_Talk_VTN = L20_1
L20_1 = "哈，哈哈。我是回到原来的世界了？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Hahaha. Ich schätze, ich bin wieder auf meiner Heimatwelt."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Ha ha ha. On dirait que je suis bel et bien de retour dans mon monde d'origine."
L19_1.m_Talk_FRA = L20_1
