L21_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@270#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 270
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 31622
