L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "KYLE_DELTA_AP_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "L"
L21_1 = "괜찮아요, 시영 씨? 무사해서 다행이에요. 일주일이나 누워 계셨다고요!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "大丈夫ですか、シノンさん？　無事でよかった。一週間も目を覚まさなかったんですよ！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Are you okay, Shiyoung? I'm so glad you're awake. You were unconscious for a week!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "你沒事吧，時雨？你已經昏迷一週了，幸好你沒事！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "เธอโอเคไหมชิยอง? ฉันดีใจมากที่เธอตื่นแล้ว เธอหมดสติไปตั้งหนึ่งสัปดาห์!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Cô ổn chứ Shiyoung? Tôi rất vui vì cô đã tỉnh. Cô đã bất tỉnh suốt một tuần!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "你没事吧，时雨？你没事真是太好了，你都躺了一周了！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Geht es dir gut, Shiyoung? Ich bin so froh, dass du endlich aufgewacht bist. Du warst eine ganz Woche lang bewusstlos!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Vous allez bien, Charlotte ? Je suis tellement soulagée que vous soyez enfin réveillée. Vous étiez inconsciente pendant une semaine !"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
