L26_1 = "켁! 카, 카린 양! 수, 숨막히니까 놓고 말해요, 놓고……!!"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "ゲッ！　か、カリンさん！　い、息ができない、とりあえず離して、話聞くから……！！"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Kgh! K-Karin! You're choking me! Let go of me, and we can talk...!"
L25_1.m_Talk_ENG = L26_1
L26_1 = "咳！卡，卡琳！我，我快沒辦法呼吸了，你先放開我再說，你先放開……！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "กก! คะ คาริน! เธอกำลังกอดฉันแน่นไป! ปล่อยฉันแล้วเราค่อยคุยกันได้...!"
L25_1.m_Talk_THA = L26_1
L26_1 = "Kgh! K-Karin! Cô đang làm tôi nghẹt thở! Buông tôi ra rồi chúng ta có thể nói chuyện...!"
L25_1.m_Talk_VTN = L26_1
L26_1 = "咳！卡、卡琳！我、我喘不上气了，你放开再说，你先放开……！"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Argh! K-Karin! Du erwürgst mich! Lass mich los und dann können wir reden ...!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Eh ! K-Karin ! Vous m'étouffez ! Lâchez-moi, on peut discuter...!"
L25_1.m_Talk_FRA = L26_1
