L32_1 = "역시 떠돌이 고양이보다는…… 그래도 사람이 더 좋네요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "やはり野良猫よりは……人間の方がいいですね。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I guess being a person is... still better than being a stray cat."
L31_1.m_Talk_ENG = L32_1
L32_1 = "果然比起流浪貓……還是做人更好一些。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "คิดว่าเป็นคน...ยังไงก็ดีกว่าเป็นแมวจรจัด"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi đoán làm người thì... vẫn tốt hơn làm một con mèo hoang."
L31_1.m_Talk_VTN = L32_1
L32_1 = "果然比起流浪猫……还是做人更好一些。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich schätze, ein Mensch zu sein ist ... immer noch besser, als eine streunende Katze zu sein."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Je suppose qu'être un humain est... toujours mieux que d'être un chat errant."
L31_1.m_Talk_FRA = L32_1
