L33_1.m_Pos = "R"
L34_1 = "이렇게 절 기다려 주는 사람이 있으니까요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "こうして私を待ってくれる人がいますから。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "I have someone waiting for me, after all."
L33_1.m_Talk_ENG = L34_1
L34_1 = "因為有人在等著我。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ฉันมีคนรอฉันอยู่ที่นี่อยู่แล้ว"
L33_1.m_Talk_THA = L34_1
L34_1 = "Rốt cuộc thì tôi cũng có người đang đợi tôi."
L33_1.m_Talk_VTN = L34_1
L34_1 = "因为会有人等着我。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ich habe schließlich jemanden, der auf mich wartet."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Au moins j'ai quelqu'un qui m'attend ici."
L33_1.m_Talk_FRA = L34_1
