L39_1 = "들었어? 아카데미의 명물, 검은 누아르 네로 블랙 3세가 원래 이 집 고양이였다지……?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "聞いた？　アカデミー名物の、黒のノワール・ネロ・ブラック3世はもともと家猫だったって話……？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Have you heard? The famous mascot of the Academy, Dark Noir Nero Black III, originally lived here..."
L38_1.m_Talk_ENG = L39_1
L39_1 = "你有聽說嗎？學院的院貓，黑嚕嚕尼洛三世本來是這家的貓欸……！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เธอเคยได้ยินไหม? มาสคอตอันโด่งดังของสถาบัน ดาร์กนัวร์ เนโร แบล็ค III เดิมทีอาศัยอยู่ที่นี่..."
L38_1.m_Talk_THA = L39_1
L39_1 = "Cô đã nghe nói chưa? Linh vật nổi tiếng của Học viện, Dark Noir Nero Black III, ban đầu sống ở đây đấy..."
L38_1.m_Talk_VTN = L39_1
L39_1 = "你听说了吗？学院的风云猫咪，黑色努亚尔尼洛三世本来是这家的猫猫哦……！"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Hast du gehört? Das berühmte Maskottchen der Akademie, Dark Noir Nero Black III., hat ursprünglich hier gelebt ..."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Tu es au courant ? Il parait que la célèbre mascotte de l'Académie, Dark Noir Nero Black III, vivait ici à l'origine..."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@289#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 289
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 31622
L39_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "맞아, 아까 물어봤는데 원래 이름은 <color=#ffd34c>플루토</color>라고 하더라?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "そうそう、さっき聞いたけど、元の名前は<color=#ffd34c>プルートー</color>って言うんだって。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Yeah, I asked earlier, and it seems like its real name is <color=#ffd34c>Pluto</color>."
L39_1.m_Talk_ENG = L40_1
L40_1 = "沒錯，我剛有去問，牠原本叫<color=#ffd34c>布魯托</color>。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ใช่ ฉันเคยถามไปก่อนหน้านี้ และดูเหมือนว่าชื่อจริงของมันคือ <color=#ffd34c>พลูโต</color>"
L39_1.m_Talk_THA = L40_1
L40_1 = "Vâng, tôi đã hỏi trước đó và có vẻ như tên thật của nó là <color=#ffd34c>Pluto</color>."
L39_1.m_Talk_VTN = L40_1
L40_1 = "没错，我刚刚去问了，它原本叫<color=#ffd34c>布鲁托</color>。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ja, ich habe vorhin gefragt, und es scheint, als wäre sein richtiger Name <color=#ffd34c>Pluto</color>."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Oui, j'ai demandé tout à l'heure, et il semble que son vrai nom soit <color=#ffd34c>Pluto</color>."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@290#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 290
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 31622
L40_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "불운을 미리 알려주는 고양이였다고 해."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "不運を事前に知らせてくれる猫だったらしいよ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Apparently he's a cat that predicts misfortune."
L40_1.m_Talk_ENG = L41_1
L41_1 = "據說是個可以預知不幸的貓。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "มันคือแมวที่ทำนายโชคร้าย"
L40_1.m_Talk_THA = L41_1
L41_1 = "Rõ ràng nó là một con mèo dự đoán những điều không may."
L40_1.m_Talk_VTN = L41_1
L41_1 = "据说是个可以预知不幸的猫。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Anscheinend ist er eine Katze, die Unglück voraussagt."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Apparemment, c'est un chat qui prédit les malheurs."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@291#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 291
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 31622
L41_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "카운터와 싸워 이기고…… 미적분을 풀면서…… 불운까지 예지한다고……? 진짜 대단한 고양이잖아!?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "カウンターと喧嘩して勝って……微分積分の問題が解けて……不運まで予知するの……？　本当にすごい猫じゃない！"
L41_1.m_Talk_JPN = L42_1
L42_1 = "So... he fights Counters... solves calculous problems... AND predicts misfortune...? What a ridiculous cat!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "打贏制裁者……會解微積分……還能預知不幸……？好厲害的貓喔？！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ดังนั้น... พวกเขาต่อสู้กับเคาน์เตอร์... จากการแก้ปัญหาและคำนวณ... คำทำนายโชคร้าย...? มันช่างเป็นแมวที่ไร้สาระมาก!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Vì vậy... Nó chiến đấu với Counters... giải quyết các phép tính... VÀ dự đoán những điều không may...? Thật là một con mèo buồn cười!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "打赢制裁者……会解微积分……还能预知不幸……？好厉害的猫啊？！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Also kämpft er gegen Counter ... löst Rechenaufgaben ... und sagt Unglück voraus ...? Was für eine außergewöhnliche Katze!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Alors comme ça... Il se bat contre des Counters... Peut résoudre des problèmes de maths... et peut même prédire les malheurs...? Mais c'est incroyable !"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@292#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 292
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 31622
