L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "우리 고양이 강도단이 이런 명물 고양이의 사진을 놓칠 수는 없지."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "私たち猫ハンターズにとって、こんな名物猫の写真を撮り逃すわけには行かないわね。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "As Cat Lovers Extraordinaire, we must get more pictures of that cat."
L42_1.m_Talk_ENG = L43_1
L43_1 = "我們貓咪控社團絕不能錯過這麼出色的貓咪照片！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ในฐานะ นักล่าสุดยอดคนรักแมว เราจะต้องเก็บภาพแมวตัวนั้นให้ได้มากกว่านี้"
L42_1.m_Talk_THA = L43_1
L43_1 = "Với tư cách là Hội Con Sen Yêu Mèo, chúng ta phải có thêm nhiều bức ảnh về con mèo đó."
L42_1.m_Talk_VTN = L43_1
L43_1 = "我们猫咪强盗团绝不能错过这么出色的猫咪照片！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Als „Club der Katzenliebhaber“ müssen wir unbedingt viel mehr Fotos von dieser Katze machen."
L42_1.m_Talk_DEU = L43_1
L43_1 = "En tant qu'Amoureux des chats, nous devons obtenir plus de photos de lui !"
L42_1.m_Talk_FRA = L43_1
