L47_1 = "하, 하하. 손님……?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "は、はは。お客様……？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Hah, ha ha. How can I help you...?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "哈，哈哈，這位客人……？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ฮ่า ฮ่า ฮ่า ฉันจะช่วยเธอได้ยังไง...?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ha, ha ha. Tôi giúp cô thế nào đây...?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "哈，哈哈，客人……？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Hahaha. Wie kann ich dir helfen ...?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Ha ha ha. Qu'est-ce que je vous sers ?"
