L47_1.m_Face = "UNIT_IDLE"
L47_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L47_1.m_Pos = "C"
L48_1 = "네로 란체스터 3세의 1일 3간식은 꾸준히 지켜지고 있는 거겠죠?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "ネロ・ランチェスター3世の1日3回のおやつはちゃんと守られていますよね？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I assume you have been providing Nero Lanchester III with 3 snacks a day, correct?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "給尼洛·蘭賈斯特三世的一日三餐，你有好好準備吧？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฉันคิดว่าเธอได้ให้ของว่าง 3 คาบ แก่ เนโร แลนเชสเตอร์ III ไม่ใช่หรอ?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi cho rằng cô đã cho Nero Lanchester III 3 bữa ăn nhẹ mỗi ngày, đúng không?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "给尼洛·兰切斯特三世的一日三餐，你有好好准备吧？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ich gehe davon aus, dass du Nero Lanchester III. mit 3 Leckerlis pro Tag versorgst, richtig?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Vous continuez à donner trois collations par jour à Nero Lanchester III 3, n'est-ce pas ?"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@298#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 298
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 31622
L48_1.m_CutScenStrID = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2"
L48_1.m_bWaitClick = true
