L48_1.m_CharStrID = "PRESIDENT_SCHOOL_NULL_NULL"
L48_1.m_Pos = "C"
L49_1 = "털손질은……? 재우기 전에 자장가는 불러주고 있으신가요?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "毛の手入れは……？　眠る前に子守唄は歌っていますか？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "And fur maintenance...? Are you singing a lullaby before putting him to bed?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "梳毛呢……？睡覺之前會給牠唱搖籃曲吧？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "และการบำรุงขนเธอ...? เธอได้ร้องเพลงกล่อมเธอก่อนนอนหรือเปล่า?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Và chăm sóc lông...? Cô có hát ru trước khi cho em ấy đi ngủ không?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "梳毛呢……？睡觉之前会给它唱摇篮曲吧？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Du pflegst auch sein Fell ...? Und singst ihm ein Schlaflied, bevor du ihn ins Bett bringst?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Prenez-vous soin de son pelage ? Lui chantez-vous une berceuse avant de le mettre au lit ?"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
