L50_1 = "그러니까, 뒤에 기다리시는 분이 많아서……"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ですから、後ろに並んでいる方が多くいらっしゃるので……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Um, t-there are a lot of people waiting in line behind you, so..."
L49_1.m_Talk_ENG = L50_1
L50_1 = "那個，後面還有很多客人在等……"
L49_1.m_Talk_TWN = L50_1
L50_1 = "เอ่อ มีคนมากมายรออยู่ข้างหลัง เยอะมาก ดังนั้น..."
L49_1.m_Talk_THA = L50_1
L50_1 = "Ừm, có rất nhiều người xếp hàng chờ phía sau, nên..."
L49_1.m_Talk_VTN = L50_1
L50_1 = "那个，后面还有很多客人在等着……"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ähm, es gibt viele Leute, die hinter dir in der Schlange warten, also ..."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Euh... Il y a beaucoup de gens qui font la queue derrière vous, alors..."
L49_1.m_Talk_FRA = L50_1
