L51_1 = "有關布魯托的問題還是之後再……"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ฉันจะตอบคำถามของเธอเกี่ยวกับพลูโตในภายหลังนะ..."
L50_1.m_Talk_THA = L51_1
L51_1 = "Chúng tôi sẽ trả lời câu hỏi của cô về Pluto sau nhé..."
L50_1.m_Talk_VTN = L51_1
L51_1 = "关于布鲁托的提问还是等以后……"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Wir werden deine Fragen zu Pluto später beantworten ..."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Je répondrai à vos questions sur Pluto plus tard..."
L50_1.m_Talk_FRA = L51_1
