L3_1 = "LAURA_STREGA_EVENT_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "뭐야? 막무가내로 플루토 사진을 찍어가겠다는 진상들이 왜 이렇게 많아!?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "何だ？　この無理やりプルートーの写真を撮ろうとする迷惑な連中の多さは！？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "What's happening? Why are so many guests trying to force their way in and take pictures of Pluto?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "什麼？怎麼有這麼奧客硬要拍布魯托的照片？！"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เกิดอะไรขึ้น? ทำไมแขกจำนวนมากถึงพยายามจะเข้าไปถ่ายรูปพลูโตล่ะ?"
L2_1.m_Talk_THA = L3_1
L3_1 = "Chuyện gì vậy? Tại sao có nhiều khách cố gắng chen vào và chụp ảnh Pluto thế?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "什么？怎么有这么多难缠的客人非要拍布鲁托的照片啊？！"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Was ist passiert? Warum versuchen so viele Gäste, sich hier reinzudrängen und Pluto zu fotografieren?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Qu'est-ce qui se passe ? Pourquoi il y a tous ces tarés qui s'obstinent à essayer de prendre Pluto en photo ?!"
L2_1.m_Talk_FRA = L3_1
