L4_1 = "LAURA_STREGA_EVENT_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L3_1.m_Crash = 20
L4_1 = "그 여자…… 대체 플루토의 몸으로 대체 무슨 짓을 하고 다닌 거야!"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "あの女……いったいプルートーの身体で何をして回ってたんだ！"
L3_1.m_Talk_JPN = L4_1
L4_1 = "That woman... What did she do while she was in Pluto's body?!"
L3_1.m_Talk_ENG = L4_1
L4_1 = "那個女人……在布魯托身體裡的時候都做了什麼好事！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ผู้หญิงคนนั้น... เธอทำอะไรในขณะที่อยู่ในร่างพลูโตหรอ!"
L3_1.m_Talk_THA = L4_1
L4_1 = "Cô gái đó... Cô ấy đã làm gì khi ở trong cơ thể của Pluto?!"
L3_1.m_Talk_VTN = L4_1
L4_1 = "那个女人……在布鲁托身体里的时候都干了些什么事啊！"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Diese Frau ... Was hat sie bloß getan, während sie in Plutos Körper gesteckt hat?!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Cette femme... qu'a-t-elle fait pendant qu'elle était dans le corps de Pluto ?!"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "COUNTERCASE_FENRIR_JOOSHIYOON_AP_NORMAL_2@304#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 304
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 31622
