L5_1 = "LAURA_STREGA_EVENT_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "다음에 만나면, 책장에 새끼 발까락을 찧는 저주를 걸어버리겠어."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "次会ったら、本棚の角に足の小指をぶつける呪いをかけてやる。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Next time I see her, I'll bestow a curse on her that makes her stub her toe on bookshelves."
L4_1.m_Talk_ENG = L5_1
L5_1 = "下次再讓我遇到，我一定要詛咒她小拇指撞到書櫃。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ต่อไปถ้าฉันเห็นเธอ ฉันจะสาปแช่งเธอทำให้เธอลำบากแทบจรดเท้าเลย"
L4_1.m_Talk_THA = L5_1
L5_1 = "Lần tới gặp cô ấy, tôi sẽ nguyền rủa khiến cô ấy vấp chân vào giá sách."
L4_1.m_Talk_VTN = L5_1
L5_1 = "下次遇到了，我一定要诅咒她小脚趾磕到书本架子。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Wenn ich sie das nächste Mal sehe, werde ich ihr einen Fluch auferlegen, der sie dazu bringt, sich an jedem einzelnen Bücherregal den Zeh zu stoßen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "La prochaine fois que je la vois, je lui lancerai une malédiction qui lui fera se cogner les orteils sur les coins d'étagère."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
