L6_1 = "플루토! 넌 그 여자 얼굴…… 알고 있지!?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "プルートー！　あの女の顔……覚えているな！？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Pluto! You know what she looks like... right?!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "布魯托！你記得……那女的長相吧？！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "พลูโต!เธอรู้ไหมว่าเธอหน้าตาเป็นยังไง... ใช่ไหม?!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Pluto! Mày biết cô ấy trông như thế nào... phải không?!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "布鲁托！你是不是知道……那个女的长什么样？！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Pluto! Du weißt doch, wie sie aussieht ... oder?!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Pluto ! Tu sais à quoi elle ressemble... non ?!"
L5_1.m_Talk_FRA = L6_1
